insert into public.jornadas (id, titulo, descricao, duracao_dias, status) values
  ('22222222-2222-2222-2222-222222222222', 'Fundamentos emocionais: 9 dias de psicoeducação', 'Nove módulos práticos sobre emoções, pensamentos, autocompaixão, ansiedade, perfeccionismo, imagem corporal, limites, hábitos e prevenção de recaídas — com base em psicologia científica.', 9, 'rascunho');

insert into public.jornada_atividades (jornada_id, numero_dia, titulo, conteudo, conteudo_estruturado, schema_version) values
  ('22222222-2222-2222-2222-222222222222', 1, 'Dia 1: Entendendo minhas emoções', 'Entender para que servem as emoções e treinar reconhecer, nomear e diferenciar o que você sente — emoção, pensamento, sensação física e comportamento — em vez de misturar tudo em "estou mal".



Emoções não são um defeito nem um exagero: são sinais rápidos que o corpo e a mente produzem para te avisar de algo importante — uma necessidade, um limite, um risco, uma conexão. Medo sinaliza ameaça, raiva costuma sinalizar que um limite foi ultrapassado, tristeza costuma sinalizar perda, alegria costuma sinalizar que algo te faz bem. Nenhuma emoção é "errada" de se sentir; o que varia é o que fazemos com ela.

É comum confundir quatro coisas diferentes: a emoção em si (ex.: ansiedade), o pensamento que vem junto (ex.: "vou fazer besteira"), a sensação física (ex.: aperto no peito, mãos suando) e o comportamento que ela puxa (ex.: evitar a situação). Elas se influenciam, mas são partes diferentes — separar essas partes é o primeiro passo para lidar melhor com qualquer uma delas.

Quanto mais específico o nome que você dá para uma emoção — "frustração" em vez de só "mal", "decepção" em vez de só "ruim" — mais fácil fica entender do que você precisa naquele momento. Pesquisa em psicologia chama isso de diferenciação emocional, e ela está associada a formas mais saudáveis de lidar com emoções difíceis.

Por trás de quase toda emoção intensa existe uma necessidade — de descanso, de segurança, de ser ouvida, de conexão, de reconhecimento, de espaço. Nem sempre dá para atender a necessidade na hora, mas só de identificá-la você já ganha clareza sobre o que fazer a seguir.', '{"schemaVersion":1,"objetivo":"Entender para que servem as emoções e treinar reconhecer, nomear e diferenciar o que você sente — emoção, pensamento, sensação física e comportamento — em vez de misturar tudo em \"estou mal\".","duracaoEstimadaMinutos":8,"explicacao":["Emoções não são um defeito nem um exagero: são sinais rápidos que o corpo e a mente produzem para te avisar de algo importante — uma necessidade, um limite, um risco, uma conexão. Medo sinaliza ameaça, raiva costuma sinalizar que um limite foi ultrapassado, tristeza costuma sinalizar perda, alegria costuma sinalizar que algo te faz bem. Nenhuma emoção é \"errada\" de se sentir; o que varia é o que fazemos com ela.","É comum confundir quatro coisas diferentes: a emoção em si (ex.: ansiedade), o pensamento que vem junto (ex.: \"vou fazer besteira\"), a sensação física (ex.: aperto no peito, mãos suando) e o comportamento que ela puxa (ex.: evitar a situação). Elas se influenciam, mas são partes diferentes — separar essas partes é o primeiro passo para lidar melhor com qualquer uma delas.","Quanto mais específico o nome que você dá para uma emoção — \"frustração\" em vez de só \"mal\", \"decepção\" em vez de só \"ruim\" — mais fácil fica entender do que você precisa naquele momento. Pesquisa em psicologia chama isso de diferenciação emocional, e ela está associada a formas mais saudáveis de lidar com emoções difíceis.","Por trás de quase toda emoção intensa existe uma necessidade — de descanso, de segurança, de ser ouvida, de conexão, de reconhecimento, de espaço. Nem sempre dá para atender a necessidade na hora, mas só de identificá-la você já ganha clareza sobre o que fazer a seguir."],"exemplo":{"titulo":"Um exemplo do dia a dia","texto":"Marina recebeu uma mensagem da chefe pedindo para refazer um relatório \"com mais cuidado da próxima vez\". Sensação física: estômago apertado, rosto quente. Pensamento automático: \"ela acha que eu sou incompetente\". Emoção: vergonha, com um pouco de ansiedade misturada, intensidade 7 de 10. Comportamento: releu a mensagem cinco vezes e evitou responder por duas horas. Ao nomear separadamente cada parte, Marina percebeu que a necessidade por trás da vergonha era de sentir que seu trabalho tem valor — e que isso era diferente de \"ser incompetente\". Ela decidiu responder pedindo um exemplo concreto do que a chefe esperava, em vez de ficar remoendo em silêncio."},"exercicio":{"introducao":"Pense em uma situação recente (das últimas 48 horas, se possível) em que você sentiu uma emoção com alguma intensidade. Vamos separar as partes, uma de cada vez.","campos":[{"tipo":"texto_longo","id":"situacao","rotulo":"O que aconteceu? Descreva a situação de forma simples e concreta.","placeholder":"Ex.: recebi uma mensagem da minha chefe pedindo para refazer um relatório...","maxCaracteres":600},{"tipo":"escolha_unica","id":"emocao","rotulo":"Qual emoção mais se aproxima do que você sentiu?","opcoes":["Tristeza","Raiva","Medo","Vergonha","Culpa","Alegria","Alívio","Surpresa","Nojo/repulsa","Outra ou uma mistura de várias"]},{"tipo":"escala","id":"intensidade","rotulo":"Em que intensidade você sentiu essa emoção?","min":0,"max":10,"rotuloMin":"Bem leve","rotuloMax":"Muito intensa"},{"tipo":"multipla_escolha","id":"sensacoes_fisicas","rotulo":"Que sensações físicas vieram junto? (pode marcar mais de uma)","opcoes":["Aperto no peito ou na garganta","Estômago embrulhado ou apertado","Coração acelerado","Tensão nos ombros ou mandíbula","Rosto quente ou corado","Cansaço ou peso no corpo","Não percebi nenhuma sensação clara"]},{"tipo":"texto_longo","id":"pensamentos","rotulo":"Que pensamentos passaram pela sua cabeça nesse momento?","placeholder":"Ex.: \"ela acha que eu sou incompetente\", \"eu devia ter percebido antes\"...","maxCaracteres":600,"opcional":true},{"tipo":"escolha_unica","id":"necessidade","rotulo":"Olhando agora, qual necessidade parece estar por trás dessa emoção?","opcoes":["Descanso","Segurança","Ser ouvida ou compreendida","Reconhecimento pelo que eu faço","Conexão com alguém","Espaço e autonomia","Conforto","Ainda não sei identificar"]}]},"feedback":{"padrao":"Obrigada por colocar isso em palavras — só o gesto de separar situação, emoção, corpo e pensamento já é um exercício de autoconhecimento, mesmo quando a clareza ainda não é total.","regras":[{"id":"intensidade-alta","condicoes":[{"campoId":"intensidade","operador":"maior_ou_igual","valor":8}],"texto":"Uma intensidade tão alta faz sentido diante do que você descreveu — emoções fortes não são exagero, são o corpo sinalizando que algo importante está em jogo. Se ainda estiver muito presente, pode ajudar respirar fundo algumas vezes antes de seguir."},{"id":"emocao-vergonha","condicoes":[{"campoId":"emocao","operador":"igual","valor":"Vergonha"}],"texto":"A vergonha costuma aparecer quando sentimos que algo em nós pode ser julgado — mas o que os outros pensam nem sempre reflete o que realmente somos. Vale perguntar: essa vergonha está falando sobre o que eu fiz, ou sobre quem eu acho que sou?"},{"id":"emocao-raiva","condicoes":[{"campoId":"emocao","operador":"igual","valor":"Raiva"}],"texto":"A raiva costuma aparecer quando um limite importante foi ultrapassado. Ela não precisa ser \"resolvida\" imediatamente — só reconhecê-la já ajuda a decidir com mais calma o que fazer com ela."},{"id":"emocao-medo","condicoes":[{"campoId":"emocao","operador":"igual","valor":"Medo"}],"texto":"O medo é o corpo tentando te proteger de algo que parece ameaçador — mesmo quando a ameaça é incerta ou não vai se concretizar. Nomear o medo específico (medo de quê, exatamente?) costuma reduzir um pouco o peso dele."},{"id":"necessidade-nao-sei","condicoes":[{"campoId":"necessidade","operador":"igual","valor":"Ainda não sei identificar"}],"texto":"Tudo bem não saber ainda — identificar a necessidade por trás de uma emoção é uma habilidade que se desenvolve com prática, não algo que se acerta de primeira. Só de ter parado para se perguntar isso, você já está treinando."}]},"acaoPratica":"Nas próximas 24 horas, quando notar uma emoção (mesmo pequena), tente nomeá-la com uma palavra específica — não só \"bem\" ou \"mal\". Se quiser, complete mentalmente: \"estou sentindo ___, e talvez o que eu precise agora seja ___\".","resumo":["Emoções são sinais com função, não defeitos — elas indicam necessidades, limites ou riscos.","Emoção, pensamento, sensação física e comportamento são partes diferentes de uma mesma experiência.","Nomear a emoção com mais precisão ajuda a entender melhor o que fazer a seguir.","Quase toda emoção intensa aponta para uma necessidade — identificá-la já é um passo de cuidado, mesmo sem conseguir atendê-la na hora."],"baseCientifica":[{"afirmacao":"Emoções cumprem uma função adaptativa: preparam o corpo e orientam o comportamento diante de eventos relevantes (ex.: medo sinaliza ameaça, raiva sinaliza violação de limites).","referencia":"Gross, J. J. (1998). The Emerging Field of Emotion Regulation: An Integrative Review. Review of General Psychology, 2(3), 271–299.","link":"https://doi.org/10.1037/1089-2680.2.3.271","aplicacao":"Base para a explicação de que emoções têm função e para o modelo de que emoção, pensamento e comportamento são processos relacionados mas distintos.","limitacoes":"É um artigo teórico de revisão, não um estudo experimental isolado; o modelo processual de regulação emocional descrito é amplamente aceito, mas simplifica um fenômeno multifatorial."},{"afirmacao":"Nomear emoções com mais precisão e especificidade (diferenciação emocional) está associado a formas mais adaptativas de lidar com experiências negativas.","referencia":"Kashdan, T. B., Barrett, L. F., & McKnight, P. E. (2015). Unpacking Emotion Differentiation: Transforming Unpleasant Experience by Perceiving Distinctions in Negativity. Current Directions in Psychological Science, 24(1), 10–16.","link":"https://doi.org/10.1177/0963721414550708","aplicacao":"Fundamenta o exercício de escolher uma emoção específica em vez de ficar em \"bem/mal\", e a orientação da explicação sobre nomear com precisão.","limitacoes":"A relação é correlacional em boa parte dos estudos citados nessa revisão — diferenciação emocional está associada a, mas não comprovadamente causa isoladamente, melhor regulação emocional."}],"avisoSeguranca":"Se, ao descrever a situação, vier à tona algo como pensamentos de se machucar, violência ou uma situação de abuso, isso merece um cuidado maior do que este exercício sozinho pode oferecer — role até o final para ver como buscar apoio.","camposParaTriagem":["situacao","pensamentos"]}'::jsonb, 1),
  ('22222222-2222-2222-2222-222222222222', 2, 'Dia 2: Pensamentos não são fatos', 'Entender que pensamentos são interpretações automáticas, não fatos, e treinar reconhecer distorções cognitivas comuns e construir um pensamento alternativo mais equilibrado — sem cair em positividade forçada.



Toda hora sua mente produz interpretações automáticas dos eventos — chamamos isso de pensamentos automáticos. Eles surgem tão rápido que costumam parecer verdades óbvias, não hipóteses. Mas um pensamento é só a primeira leitura que a mente faz de uma situação, baseada em experiências passadas, humor do momento e atalhos mentais — não uma descrição objetiva do que está acontecendo. Duas pessoas podem viver exatamente a mesma situação e ter pensamentos automáticos completamente diferentes sobre ela.

O motivo de prestar atenção nisso é que pensamento, emoção e comportamento se retroalimentam: pensar "vou estragar tudo" tende a gerar ansiedade, e a ansiedade tende a puxar comportamentos de evitação ou de controle excessivo, que por sua vez reforçam o pensamento original. Esse ciclo pode rodar horas sem que você perceba que tudo começou numa interpretação automática — não num fato verificado.

Existem padrões comuns de pensamento automático, chamados de distorções cognitivas, que tendem a distorcer a realidade numa direção mais negativa ou mais rígida do que ela é. Algumas das mais frequentes: catastrofização (assumir que o pior cenário vai acontecer — "se eu errar essa entrega, vou ser demitida"); leitura mental (supor o que o outro está pensando sem checar — "ela não respondeu, deve estar puta comigo"); tudo-ou-nada (ver as coisas só em extremos, sem meio-termo — "se não for perfeito, é um fracasso total"); generalização excessiva (transformar um evento isolado numa regra geral — "não consegui dessa vez, eu nunca consigo nada"); e desqualificar o positivo (descartar o que deu certo como se não contasse — "isso só deu certo porque tive sorte, não porque eu sou capaz").

O objetivo de analisar um pensamento não é substituí-lo por um pensamento "positivo" à força. Dizer para si mesma "vai dar tudo certo" quando você não sabe se vai dar certo é só trocar uma distorção por outra — e geralmente não convence ninguém, muito menos você mesma. O objetivo é um pensamento mais equilibrado e realista: um que leve em conta as evidências a favor e as evidências contra, reconheça o que é incerto, e deixe espaço para nuance. Às vezes o pensamento equilibrado ainda é difícil ou desconfortável — e tudo bem, porque ele é mais honesto do que a catástrofe automática e mais sustentável do que o otimismo forçado.', '{"schemaVersion":1,"objetivo":"Entender que pensamentos são interpretações automáticas, não fatos, e treinar reconhecer distorções cognitivas comuns e construir um pensamento alternativo mais equilibrado — sem cair em positividade forçada.","duracaoEstimadaMinutos":9,"explicacao":["Toda hora sua mente produz interpretações automáticas dos eventos — chamamos isso de pensamentos automáticos. Eles surgem tão rápido que costumam parecer verdades óbvias, não hipóteses. Mas um pensamento é só a primeira leitura que a mente faz de uma situação, baseada em experiências passadas, humor do momento e atalhos mentais — não uma descrição objetiva do que está acontecendo. Duas pessoas podem viver exatamente a mesma situação e ter pensamentos automáticos completamente diferentes sobre ela.","O motivo de prestar atenção nisso é que pensamento, emoção e comportamento se retroalimentam: pensar \"vou estragar tudo\" tende a gerar ansiedade, e a ansiedade tende a puxar comportamentos de evitação ou de controle excessivo, que por sua vez reforçam o pensamento original. Esse ciclo pode rodar horas sem que você perceba que tudo começou numa interpretação automática — não num fato verificado.","Existem padrões comuns de pensamento automático, chamados de distorções cognitivas, que tendem a distorcer a realidade numa direção mais negativa ou mais rígida do que ela é. Algumas das mais frequentes: catastrofização (assumir que o pior cenário vai acontecer — \"se eu errar essa entrega, vou ser demitida\"); leitura mental (supor o que o outro está pensando sem checar — \"ela não respondeu, deve estar puta comigo\"); tudo-ou-nada (ver as coisas só em extremos, sem meio-termo — \"se não for perfeito, é um fracasso total\"); generalização excessiva (transformar um evento isolado numa regra geral — \"não consegui dessa vez, eu nunca consigo nada\"); e desqualificar o positivo (descartar o que deu certo como se não contasse — \"isso só deu certo porque tive sorte, não porque eu sou capaz\").","O objetivo de analisar um pensamento não é substituí-lo por um pensamento \"positivo\" à força. Dizer para si mesma \"vai dar tudo certo\" quando você não sabe se vai dar certo é só trocar uma distorção por outra — e geralmente não convence ninguém, muito menos você mesma. O objetivo é um pensamento mais equilibrado e realista: um que leve em conta as evidências a favor e as evidências contra, reconheça o que é incerto, e deixe espaço para nuance. Às vezes o pensamento equilibrado ainda é difícil ou desconfortável — e tudo bem, porque ele é mais honesto do que a catástrofe automática e mais sustentável do que o otimismo forçado."],"exemplo":{"titulo":"Um exemplo do dia a dia","texto":"Bianca mandou uma mensagem de bom dia para uma amiga e, três horas depois, ainda não tinha resposta. Pensamento automático: \"ela está brava comigo, deve ser por causa daquele comentário que eu fiz semana passada\" (leitura mental). Emoção: ansiedade, intensidade 6 de 10. Comportamento: releu a conversa antiga várias vezes procurando o que teria feito de errado. Ao parar para checar evidências, Bianca notou: a favor do pensamento, nada concreto — só a demora em responder; contra o pensamento, a amiga tinha avisado outro dia que a semana estaria corrida no trabalho, e a última conversa das duas tinha terminado bem, com risadas. Pensamento alternativo: \"ela pode estar ocupada, ou pode ter algum outro motivo que eu não sei — não tenho evidência real de que está brava, só uma suposição\". Isso não apagou a ansiedade na hora, mas tirou o peso de uma certeza que não existia."},"exercicio":{"introducao":"Pense numa situação recente em que você teve um pensamento automático que gerou desconforto. Vamos separar as partes e olhar as evidências com calma, sem pressa de \"pensar positivo\".","campos":[{"tipo":"texto_longo","id":"situacao","rotulo":"O que aconteceu? Descreva a situação de forma simples e concreta.","placeholder":"Ex.: mandei uma mensagem e fiquei horas sem resposta...","maxCaracteres":600},{"tipo":"texto_longo","id":"pensamento_automatico","rotulo":"Qual foi o primeiro pensamento que passou pela sua cabeça nessa situação?","placeholder":"Ex.: \"ela está brava comigo\"...","maxCaracteres":400},{"tipo":"escolha_unica","id":"emocao","rotulo":"Qual emoção veio junto com esse pensamento?","opcoes":["Ansiedade","Tristeza","Raiva","Vergonha","Culpa","Medo","Frustração","Outra ou uma mistura de várias"]},{"tipo":"escala","id":"intensidade","rotulo":"Em que intensidade você sentiu essa emoção?","min":0,"max":10,"rotuloMin":"Bem leve","rotuloMax":"Muito intensa"},{"tipo":"texto_longo","id":"evidencias_a_favor","rotulo":"Que evidências concretas (fatos, não suposições) apoiam esse pensamento?","placeholder":"Ex.: ela demorou para responder...","maxCaracteres":500,"opcional":true},{"tipo":"texto_longo","id":"evidencias_contra","rotulo":"Que evidências concretas contradizem ou enfraquecem esse pensamento?","placeholder":"Ex.: ela tinha avisado que a semana estaria corrida...","maxCaracteres":500,"opcional":true},{"tipo":"texto_longo","id":"pensamento_alternativo","rotulo":"Levando em conta as evidências dos dois lados, como ficaria um pensamento mais equilibrado e realista sobre essa situação? (não precisa ser positivo, só mais honesto com o que você realmente sabe)","placeholder":"Ex.: \"não tenho certeza do motivo, pode ser isso ou outra coisa\"...","maxCaracteres":500}]},"feedback":{"padrao":"Obrigada por parar e olhar para esse pensamento com mais calma. Separar o pensamento automático das evidências reais é um exercício que fica mais fácil com a prática — nenhuma tentativa é perfeita, e cada uma conta.","regras":[{"id":"intensidade-alta","condicoes":[{"campoId":"intensidade","operador":"maior_ou_igual","valor":8}],"texto":"Faz sentido essa emoção ter vindo forte — quando um pensamento automático parece muito certo, o corpo reage como se já fosse um fato consumado. Vale lembrar: a intensidade da emoção não é prova de que o pensamento é verdadeiro."},{"id":"emocao-ansiedade","condicoes":[{"campoId":"emocao","operador":"igual","valor":"Ansiedade"}],"texto":"Pensamentos automáticos ligados à ansiedade costumam antecipar o pior cenário como se fosse o mais provável. Vale perguntar: esse é o único desfecho possível, ou só o mais assustador entre vários?"},{"id":"emocao-vergonha","condicoes":[{"campoId":"emocao","operador":"igual","valor":"Vergonha"}],"texto":"Pensamentos ligados à vergonha costumam vir com generalizações duras sobre quem você é, a partir de um único evento. Um erro ou uma situação difícil descreve o que aconteceu, não a sua identidade inteira."},{"id":"evidencias-contra-preenchidas","condicoes":[{"campoId":"evidencias_contra","operador":"preenchido"}],"texto":"Reparar em evidências que contradizem o pensamento automático é justamente o que ajuda a criar distância dele — mesmo quando o desconforto não desaparece por completo."},{"id":"pensamento-alternativo-preenchido","condicoes":[{"campoId":"pensamento_alternativo","operador":"preenchido"}],"texto":"Chegar a um pensamento mais equilibrado não significa que ele vai parecer 100% verdadeiro na hora — é normal ainda sentir puxão para a versão antiga. Com repetição, o pensamento mais realista tende a ficar mais acessível."}]},"acaoPratica":"Nas próximas 24 horas, quando notar um pensamento automático incomodando você, tente perguntar: \"isso é um fato ou uma interpretação?\" e \"que evidência real eu tenho disso?\". Não precisa resolver tudo, só notar a diferença já ajuda.","resumo":["Pensamentos são interpretações automáticas, não descrições objetivas da realidade.","Distorções comuns incluem catastrofização, leitura mental, tudo-ou-nada, generalização excessiva e desqualificar o positivo.","O objetivo é um pensamento mais equilibrado e realista, não um pensamento \"positivo\" forçado.","Olhar evidências a favor e contra ajuda a criar distância do pensamento automático, mesmo sem apagar o desconforto."],"baseCientifica":[{"afirmacao":"A terapia cognitivo-comportamental, que ensina a identificar e reavaliar pensamentos automáticos e distorções cognitivas, tem eficácia bem documentada para diversos quadros emocionais.","referencia":"Hofmann, S. G., Asnaani, A., Vonk, I. J. J., Sawyer, A. T., & Fang, A. (2012). The Efficacy of Cognitive Behavioral Therapy: A Review of Meta-analyses. Cognitive Therapy and Research, 36(5), 427–440.","link":"https://doi.org/10.1007/s10608-012-9476-1","aplicacao":"Fundamenta a abordagem geral do módulo — a ideia de que treinar reavaliação de pensamentos automáticos, como no exercício de evidências a favor e contra, é uma técnica com respaldo empírico.","limitacoes":"É uma revisão de meta-análises heterogêneas entre diferentes diagnósticos e populações; o tamanho do efeito varia bastante por condição, e os resultados não garantem um efeito individual específico para quem faz este exercício."},{"afirmacao":"Pensamentos automáticos negativos podem ser identificados e medidos de forma sistemática, e estão associados a estados emocionais como a ansiedade e a tristeza.","referencia":"Hollon, S. D., & Kendall, P. C. (1980). Cognitive self-statements in depression: Development of an automatic thoughts questionnaire. Cognitive Therapy and Research, 4(4), 383–395.","link":"https://doi.org/10.1007/bf01178214","aplicacao":"Base para o conceito central do módulo — o de \"pensamento automático\" como categoria distinta de fato observável — e para a estrutura do exercício de nomear o pensamento separadamente da situação.","limitacoes":"É um estudo de desenvolvimento de instrumento, com amostra de estudantes universitários da época e foco original em sintomas depressivos; não cobre necessariamente todas as populações, faixas etárias ou contextos culturais atuais."}],"camposParaTriagem":["situacao","pensamento_automatico","evidencias_a_favor","evidencias_contra"]}'::jsonb, 1),
  ('22222222-2222-2222-2222-222222222222', 3, 'Dia 3: Autocompaixão e autocrítica', 'Entender a diferença entre autocompaixão, autoestima e autocomplacência, reconhecer como a autocrítica dura tende a prejudicar (não melhorar) o bem-estar e a motivação, e praticar os três elementos da autocompaixão diante de uma situação real.



É fácil confundir autocompaixão com autoestima ou com "se dar bem" sem responsabilidade, mas são coisas diferentes. Autoestima costuma depender de avaliação e comparação — de achar que você é boa, competente ou valiosa em relação a algum padrão ou às outras pessoas; ela sobe quando você vai bem e desaba quando você erra ou se compara desfavoravelmente. Autocompaixão não depende de desempenho: é a forma como você trata a si mesma quando erra, sofre ou não alcança o que queria — independentemente de você "merecer" ou não. E autocompaixão também não é autocomplacência: não é dar de ombros para os próprios erros, evitar responsabilidade ou se poupar de qualquer desconforto. É reconhecer o erro ou a dificuldade com honestidade, mas sem se atacar por isso — o que, na prática, costuma deixar mais fácil (não mais difícil) assumir responsabilidade e mudar de rumo.

Existe uma crença comum de que autocrítica dura funciona como um "chicote motivacional" — que se você não se cobrar com dureza, vai relaxar e piorar. Mas o efeito observado costuma ser o contrário: autocrítica excessiva tende a aumentar ansiedade e desânimo, alimentar procrastinação e medo de errar, e piorar a performance ao longo do tempo, não melhorá-la. Isso faz sentido quando você pensa em quem cresce mais rápido — quem tem alguém do lado dizendo "você é péssima, vai errar de novo", ou quem tem alguém dizendo "isso foi difícil, o que dá para ajustar da próxima vez"? O segundo tende a manter a pessoa tentando; o primeiro tende a fazer ela desistir ou evitar tentar de novo.

A pesquisadora Kristin Neff descreve a autocompaixão a partir de três elementos que trabalham juntos. O primeiro é gentileza consigo mesma, em vez de autojulgamento: falar consigo do jeito que você falaria com alguém que se importa de verdade, em vez de usar a voz mais dura que você conhece. O segundo é humanidade compartilhada, em vez de isolamento: lembrar que errar, sofrer, ter limites e falhar em algo fazem parte da experiência humana comum — não é uma falha exclusivamente sua que te separa de todo mundo, é algo que atravessa a vida de qualquer pessoa, mesmo que ela não mostre. O terceiro é atenção plena (mindfulness), em vez de superidentificação com o sofrimento: reconhecer a dor ou a frustração pelo que ela é, sem exagerá-la nem tentar empurrá-la para longe — sem se afogar nela a ponto de ela virar sua identidade inteira.

Nenhum desses três elementos exige que você minimize o que aconteceu ou finja que está tudo bem quando não está. Autocompaixão não é positividade forçada — é justiça: tratar a si mesma com o mesmo padrão de cuidado que você ofereceria a alguém que você ama, na mesma situação, sem inflar nem apagar o que de fato aconteceu.', '{"schemaVersion":1,"objetivo":"Entender a diferença entre autocompaixão, autoestima e autocomplacência, reconhecer como a autocrítica dura tende a prejudicar (não melhorar) o bem-estar e a motivação, e praticar os três elementos da autocompaixão diante de uma situação real.","duracaoEstimadaMinutos":8,"explicacao":["É fácil confundir autocompaixão com autoestima ou com \"se dar bem\" sem responsabilidade, mas são coisas diferentes. Autoestima costuma depender de avaliação e comparação — de achar que você é boa, competente ou valiosa em relação a algum padrão ou às outras pessoas; ela sobe quando você vai bem e desaba quando você erra ou se compara desfavoravelmente. Autocompaixão não depende de desempenho: é a forma como você trata a si mesma quando erra, sofre ou não alcança o que queria — independentemente de você \"merecer\" ou não. E autocompaixão também não é autocomplacência: não é dar de ombros para os próprios erros, evitar responsabilidade ou se poupar de qualquer desconforto. É reconhecer o erro ou a dificuldade com honestidade, mas sem se atacar por isso — o que, na prática, costuma deixar mais fácil (não mais difícil) assumir responsabilidade e mudar de rumo.","Existe uma crença comum de que autocrítica dura funciona como um \"chicote motivacional\" — que se você não se cobrar com dureza, vai relaxar e piorar. Mas o efeito observado costuma ser o contrário: autocrítica excessiva tende a aumentar ansiedade e desânimo, alimentar procrastinação e medo de errar, e piorar a performance ao longo do tempo, não melhorá-la. Isso faz sentido quando você pensa em quem cresce mais rápido — quem tem alguém do lado dizendo \"você é péssima, vai errar de novo\", ou quem tem alguém dizendo \"isso foi difícil, o que dá para ajustar da próxima vez\"? O segundo tende a manter a pessoa tentando; o primeiro tende a fazer ela desistir ou evitar tentar de novo.","A pesquisadora Kristin Neff descreve a autocompaixão a partir de três elementos que trabalham juntos. O primeiro é gentileza consigo mesma, em vez de autojulgamento: falar consigo do jeito que você falaria com alguém que se importa de verdade, em vez de usar a voz mais dura que você conhece. O segundo é humanidade compartilhada, em vez de isolamento: lembrar que errar, sofrer, ter limites e falhar em algo fazem parte da experiência humana comum — não é uma falha exclusivamente sua que te separa de todo mundo, é algo que atravessa a vida de qualquer pessoa, mesmo que ela não mostre. O terceiro é atenção plena (mindfulness), em vez de superidentificação com o sofrimento: reconhecer a dor ou a frustração pelo que ela é, sem exagerá-la nem tentar empurrá-la para longe — sem se afogar nela a ponto de ela virar sua identidade inteira.","Nenhum desses três elementos exige que você minimize o que aconteceu ou finja que está tudo bem quando não está. Autocompaixão não é positividade forçada — é justiça: tratar a si mesma com o mesmo padrão de cuidado que você ofereceria a alguém que você ama, na mesma situação, sem inflar nem apagar o que de fato aconteceu."],"exemplo":{"titulo":"Um exemplo do dia a dia","texto":"Camila errou uma pergunta importante numa entrevista de emprego e saiu repetindo mentalmente \"sou burra, estraguei tudo, nunca vou conseguir uma vaga boa assim\". Ao notar esse padrão, ela tentou aplicar os três elementos: gentileza — em vez de \"sou burra\", reconheceu \"eu me atrapalhei numa pergunta, isso aconteceu, e ainda assim não define minha inteligência\"; humanidade compartilhada — lembrou que praticamente todo mundo que já fez entrevista já travou em alguma pergunta, isso não é uma falha rara e vergonhosa, é comum; atenção plena — permitiu sentir a frustração sem inflar (\"isso foi chato e frustrante\", não \"isso prova que eu sou um fracasso\"). Isso não fez a decepção sumir, mas evitou que uma entrevista ruim virasse uma sentença sobre o valor dela inteira."},"exercicio":{"introducao":"Pense em algo que você tem dito para si mesma com dureza ultimamente. Vamos experimentar reescrever isso com o mesmo padrão de cuidado que você ofereceria a alguém que você ama — sem fingir que está tudo bem, só sendo justa consigo mesma.","campos":[{"tipo":"texto_longo","id":"frase_autocritica","rotulo":"Escreva uma frase autocrítica real que você costuma pensar sobre si mesma.","placeholder":"Ex.: \"eu sempre estrago tudo\", \"eu sou incapaz de...\"","maxCaracteres":400},{"tipo":"texto_longo","id":"reescrita_compassiva","rotulo":"Agora reescreva essa mesma situação como se estivesse falando com uma amiga querida que passou por exatamente isso. Isso não é fingir que está tudo bem — é ser justa e gentil consigo mesma como você seria com alguém que você ama, reconhecendo o que de fato aconteceu, sem se atacar por isso.","placeholder":"Ex.: \"isso foi difícil, e é compreensível ter reagido assim...\"","maxCaracteres":500},{"tipo":"escolha_unica","id":"elemento_mais_dificil","rotulo":"Dos três elementos da autocompaixão, qual parece mais difícil para você agora: gentileza consigo mesma, lembrar que isso é parte da experiência humana comum, ou observar o sofrimento sem se afogar nele?","opcoes":["Gentileza consigo mesma (em vez de me julgar)","Humanidade compartilhada (lembrar que não sou a única)","Atenção plena (observar sem exagerar nem negar)","Os três parecem igualmente difíceis"]}]},"feedback":{"padrao":"Obrigada por colocar isso em palavras. Reescrever uma frase autocrítica com mais gentileza não muda o passado, mas treina um jeito diferente — e mais sustentável — de se relacionar consigo mesma.","regras":[{"id":"elemento-gentileza","condicoes":[{"campoId":"elemento_mais_dificil","operador":"igual","valor":"Gentileza consigo mesma (em vez de me julgar)"}],"texto":"Faz sentido a gentileza consigo mesma ser a parte mais difícil — para muita gente, a voz autocrítica soa mais \"responsável\" ou mais familiar do que a voz gentil. Um jeito de começar é perguntar: \"o que eu diria para uma amiga aqui?\" e tentar dizer isso para si mesma, mesmo que pareça estranho no início."},{"id":"elemento-humanidade","condicoes":[{"campoId":"elemento_mais_dificil","operador":"igual","valor":"Humanidade compartilhada (lembrar que não sou a única)"}],"texto":"É comum sentir que a própria dificuldade é única ou vergonhosa demais para ser comum — mas quase sempre outras pessoas já passaram por versões parecidas do que você está vivendo, mesmo que elas não mostrem isso abertamente."},{"id":"elemento-atencao-plena","condicoes":[{"campoId":"elemento_mais_dificil","operador":"igual","valor":"Atenção plena (observar sem exagerar nem negar)"}],"texto":"Equilibrar entre não negar o que dói e não deixar a dor tomar conta de tudo é realmente um exercício sutil. Uma pergunta que ajuda: \"estou descrevendo o que aconteceu, ou já pulei para uma conclusão sobre quem eu sou?\""},{"id":"elemento-todos-dificeis","condicoes":[{"campoId":"elemento_mais_dificil","operador":"igual","valor":"Os três parecem igualmente difíceis"}],"texto":"Faz sentido — autocompaixão é uma habilidade, não um traço que se tem ou não se tem, e como toda habilidade leva tempo para ficar mais natural. Praticar mesmo um pedacinho, como fez agora, já é o começo."},{"id":"reescrita-preenchida","condicoes":[{"campoId":"reescrita_compassiva","operador":"preenchido"}],"texto":"Reparar na diferença entre o que você diria a si mesma e o que diria a uma amiga já revela bastante — muitas vezes o padrão que aplicamos a nós mesmas é bem mais duro do que o que consideraríamos justo para outra pessoa."}]},"acaoPratica":"Nas próximas 24 horas, quando notar uma autocrítica dura, tente pausar e perguntar: \"eu diria isso para alguém que eu amo?\" Se a resposta for não, tente reformular a frase antes de deixá-la passar sem questionar.","resumo":["Autocompaixão não depende de desempenho, diferente da autoestima; e não é o mesmo que se poupar de responsabilidade.","Autocrítica dura tende a piorar ansiedade, desânimo e até a performance — não é um \"motivador eficiente\".","Os três elementos da autocompaixão são gentileza consigo mesma, humanidade compartilhada e atenção plena.","Ser gentil consigo mesma é uma questão de justiça, não de fingir que está tudo bem."],"baseCientifica":[{"afirmacao":"A autocompaixão pode ser definida e medida como um constructo composto por três elementos: gentileza consigo mesma, humanidade compartilhada e atenção plena (em oposição a autojulgamento, isolamento e superidentificação).","referencia":"Neff, K. D. (2003). The Development and Validation of a Scale to Measure Self-Compassion. Self and Identity, 2(3), 223–250.","link":"https://doi.org/10.1080/15298860309027","aplicacao":"Base direta do modelo de três elementos usado na explicação do módulo e na pergunta do exercício sobre qual elemento parece mais difícil.","limitacoes":"É um artigo de validação de escala e definição de constructo, com amostra majoritariamente universitária e americana da época; não é um estudo de eficácia de intervenção, então não mede diretamente se praticar autocompaixão muda o bem-estar ao longo do tempo."},{"afirmacao":"Níveis mais altos de autocompaixão estão associados a menos sintomas de ansiedade, depressão e sofrimento psicológico em geral.","referencia":"MacBeth, A., & Gumley, A. (2012). Exploring compassion: A meta-analysis of the association between self-compassion and psychopathology. Clinical Psychology Review, 32(6), 545–552.","link":"https://doi.org/10.1016/j.cpr.2012.06.003","aplicacao":"Fundamenta a afirmação do módulo de que autocrítica excessiva tende a prejudicar o bem-estar, sustentando a ideia central de trocar autojulgamento por autocompaixão.","limitacoes":"É uma meta-análise majoritariamente correlacional — a associação entre autocompaixão e menos sintomas não prova que praticar autocompaixão cause, isoladamente, a redução desses sintomas."}],"camposParaTriagem":["frase_autocritica","reescrita_compassiva"]}'::jsonb, 1),
  ('22222222-2222-2222-2222-222222222222', 4, 'Dia 4: Ansiedade, preocupação e ruminação', 'Diferenciar preocupação produtiva de ruminação improdutiva, reconhecer o ciclo da ansiedade, aprender uma técnica de grounding e praticar separar o que está sob seu controle do que não está, aceitando um pouco mais de incerteza.



Nem toda preocupação é igual. A preocupação produtiva é aquela que leva a uma ação concreta: você identifica um problema real, pensa em passos possíveis e, mesmo que não resolva tudo de uma vez, sai da reflexão com algo para fazer. Já a ruminação — ou preocupação improdutiva — é aquela que gira em círculo: repete o mesmo problema, os mesmos "e se", as mesmas cenas, sem gerar nenhuma ação nova, e geralmente piora o humor em vez de esclarecer alguma coisa. Uma pergunta simples ajuda a diferenciar: "esse pensamento está me levando a algum passo possível, ou só está me fazendo sentir pior sobre algo que eu já sei que existe?"

A ansiedade costuma seguir um ciclo reconhecível: um pensamento ansioso surge ("e se der errado", "e se eu não conseguir"), o corpo reage com sensações físicas (coração acelerado, aperto no peito, tensão), isso puxa um comportamento de evitação (fugir da situação) ou de controle excessivo (checar, perguntar, revisar sem parar), o que traz um alívio de curto prazo — e então a ansiedade volta, muitas vezes mais forte, porque evitar ou controlar demais ensina ao cérebro que aquilo realmente era perigoso o suficiente para merecer tanta cautela. Reconhecer esse ciclo em andamento já ajuda a interromper o piloto automático.

Uma técnica simples para interromper o ciclo no momento em que ele está acontecendo é o grounding pelos sentidos, também chamado de técnica 5-4-3-2-1: procure, ao seu redor, 5 coisas que você consegue ver, 4 coisas que consegue tocar, 3 coisas que consegue ouvir, 2 coisas que consegue cheirar, e 1 coisa que consegue provar (ou algo que você gostaria de provar). O objetivo não é resolver o problema que está te preocupando — é trazer a atenção de volta para o presente e para o corpo, dando um respiro antes de decidir o que fazer a seguir.

Outra ferramenta útil é a resolução de problemas estruturada: quando notar uma preocupação, vale perguntar se ela é sobre algo concreto e solucionável agora, ou sobre algo abstrato, incerto ou fora do seu alcance no momento. Problemas concretos podem ganhar um plano de ação, mesmo pequeno. Preocupações abstratas — sobre o futuro, sobre o que os outros pensam, sobre cenários hipotéticos — normalmente não têm uma "solução" para encontrar, e insistir em resolvê-las mentalmente tende a alimentar a ruminação. Nesses casos, o caminho costuma ser outro: praticar tolerar a incerteza em vez de tentar eliminá-la. A intolerância à incerteza — a dificuldade de aceitar que nem tudo pode ser previsto ou controlado — está associada a mais ansiedade; e a certeza total sobre o futuro raramente é possível, por mais que a mente insista em buscá-la como se fosse.', '{"schemaVersion":1,"objetivo":"Diferenciar preocupação produtiva de ruminação improdutiva, reconhecer o ciclo da ansiedade, aprender uma técnica de grounding e praticar separar o que está sob seu controle do que não está, aceitando um pouco mais de incerteza.","duracaoEstimadaMinutos":9,"explicacao":["Nem toda preocupação é igual. A preocupação produtiva é aquela que leva a uma ação concreta: você identifica um problema real, pensa em passos possíveis e, mesmo que não resolva tudo de uma vez, sai da reflexão com algo para fazer. Já a ruminação — ou preocupação improdutiva — é aquela que gira em círculo: repete o mesmo problema, os mesmos \"e se\", as mesmas cenas, sem gerar nenhuma ação nova, e geralmente piora o humor em vez de esclarecer alguma coisa. Uma pergunta simples ajuda a diferenciar: \"esse pensamento está me levando a algum passo possível, ou só está me fazendo sentir pior sobre algo que eu já sei que existe?\"","A ansiedade costuma seguir um ciclo reconhecível: um pensamento ansioso surge (\"e se der errado\", \"e se eu não conseguir\"), o corpo reage com sensações físicas (coração acelerado, aperto no peito, tensão), isso puxa um comportamento de evitação (fugir da situação) ou de controle excessivo (checar, perguntar, revisar sem parar), o que traz um alívio de curto prazo — e então a ansiedade volta, muitas vezes mais forte, porque evitar ou controlar demais ensina ao cérebro que aquilo realmente era perigoso o suficiente para merecer tanta cautela. Reconhecer esse ciclo em andamento já ajuda a interromper o piloto automático.","Uma técnica simples para interromper o ciclo no momento em que ele está acontecendo é o grounding pelos sentidos, também chamado de técnica 5-4-3-2-1: procure, ao seu redor, 5 coisas que você consegue ver, 4 coisas que consegue tocar, 3 coisas que consegue ouvir, 2 coisas que consegue cheirar, e 1 coisa que consegue provar (ou algo que você gostaria de provar). O objetivo não é resolver o problema que está te preocupando — é trazer a atenção de volta para o presente e para o corpo, dando um respiro antes de decidir o que fazer a seguir.","Outra ferramenta útil é a resolução de problemas estruturada: quando notar uma preocupação, vale perguntar se ela é sobre algo concreto e solucionável agora, ou sobre algo abstrato, incerto ou fora do seu alcance no momento. Problemas concretos podem ganhar um plano de ação, mesmo pequeno. Preocupações abstratas — sobre o futuro, sobre o que os outros pensam, sobre cenários hipotéticos — normalmente não têm uma \"solução\" para encontrar, e insistir em resolvê-las mentalmente tende a alimentar a ruminação. Nesses casos, o caminho costuma ser outro: praticar tolerar a incerteza em vez de tentar eliminá-la. A intolerância à incerteza — a dificuldade de aceitar que nem tudo pode ser previsto ou controlado — está associada a mais ansiedade; e a certeza total sobre o futuro raramente é possível, por mais que a mente insista em buscá-la como se fosse."],"exemplo":{"titulo":"Um exemplo do dia a dia","texto":"Renata tinha uma consulta médica marcada e passou a noite anterior repassando mentalmente todos os resultados possíveis, sem chegar a nenhuma conclusão nova — só sentindo o coração acelerar mais a cada rodada de pensamentos (ruminação). Ao perceber o ciclo, ela fez o 5-4-3-2-1: viu o abajur, a cortina, o teto, o celular, a porta; tocou o lençol, o travesseiro, a própria mão, a borda da cama; ouviu o ventilador, um carro passando, sua própria respiração; sentiu o cheiro do creme que tinha passado e o do quarto; e notou o gosto de menta ainda na boca de ter escovado os dentes. Depois, separou: o que estava sob seu controle era levar os exames e chegar no horário; o que estava parcialmente sob controle era como ela se preparava emocionalmente para ouvir o resultado; o que estava totalmente fora de controle era o resultado em si. Ela decidiu, como ação concreta, separar os documentos e dormir mais cedo — e aceitar que o resto ela só saberia no dia seguinte."},"exercicio":{"introducao":"Pense em algo que está te preocupando agora. Vamos usar o círculo de controle para separar o que depende de você do que não depende — sem a expectativa de que tudo precise estar sob controle.","campos":[{"tipo":"texto_longo","id":"controle_total","rotulo":"Nessa situação, o que está totalmente sob o seu controle?","placeholder":"Ex.: como eu me preparo, o que eu levo, o horário que eu saio de casa...","maxCaracteres":500},{"tipo":"texto_longo","id":"controle_parcial","rotulo":"O que está parcialmente sob o seu controle (você influencia, mas não decide sozinha)?","placeholder":"Ex.: como a conversa vai fluir, a reação da outra pessoa...","maxCaracteres":500},{"tipo":"texto_longo","id":"fora_de_controle","rotulo":"O que está totalmente fora do seu controle nessa situação?","placeholder":"Ex.: o resultado final, a decisão de outra pessoa, um evento externo...","maxCaracteres":500},{"tipo":"texto_curto","id":"acao_concreta","rotulo":"Existe uma pequena ação possível que você pode fazer hoje, relacionada à parte que está sob seu controle? (às vezes tudo está fora de controle, e não ter uma ação agora também é uma resposta válida)","placeholder":"Ex.: separar os documentos, mandar uma mensagem, dormir mais cedo...","maxCaracteres":200,"opcional":true}]},"feedback":{"padrao":"Obrigada por separar essas partes com calma. Só de distinguir o que está sob seu controle do que não está, você já está saindo do ciclo automático de tentar controlar tudo de uma vez.","regras":[{"id":"fora-de-controle-preenchido","condicoes":[{"campoId":"fora_de_controle","operador":"preenchido"}],"texto":"Reconhecer o que está fora do seu controle não é desistir — é liberar energia que estava sendo gasta tentando controlar o incontrolável, para usar no que de fato depende de você."},{"id":"acao-concreta-preenchida","condicoes":[{"campoId":"acao_concreta","operador":"preenchido"}],"texto":"Ótimo ter encontrado uma ação pequena e concreta — ações assim costumam reduzir mais a ansiedade do que continuar pensando sobre o problema, porque tiram a mente do \"e se\" e colocam no \"o que eu posso fazer agora\"."},{"id":"controle-parcial-preenchido","condicoes":[{"campoId":"controle_parcial","operador":"preenchido"}],"texto":"A parte \"parcialmente sob controle\" costuma ser a mais desconfortável, porque não é nem totalmente sua nem totalmente alheia — envolve tentar seu melhor sem poder garantir o resultado. Isso é desconfortável, mas é onde a maior parte da vida realmente acontece."},{"id":"controle-total-preenchido","condicoes":[{"campoId":"controle_total","operador":"preenchido"}],"texto":"Ter clareza sobre o que está totalmente sob seu controle é um bom ponto de partida — é aí que qualquer ação concreta tende a fazer mais diferença."}]},"acaoPratica":"Na próxima vez que perceber uma preocupação girando sem gerar nenhuma ação, experimente o 5-4-3-2-1: nomeie 5 coisas que vê, 4 que toca, 3 que ouve, 2 que cheira e 1 que prova. Depois, pergunte-se se há algum passo pequeno e concreto que você pode dar agora — e se não houver, tudo bem também.","resumo":["Preocupação produtiva leva a uma ação concreta; ruminação gira em círculo sem gerar solução.","O ciclo da ansiedade envolve pensamento, sensação física, evitação ou controle excessivo, alívio curto e retorno da ansiedade.","A técnica 5-4-3-2-1 usa os cinco sentidos para trazer a atenção de volta ao presente.","Separar o que está sob controle, parcialmente sob controle e fora de controle ajuda a direcionar energia com mais realismo.","Tolerar um pouco de incerteza costuma ajudar mais do que tentar eliminar toda incerteza, que raramente é possível."],"baseCientifica":[{"afirmacao":"A preocupação é um processo cognitivo específico, ligado a tentativas mentais de evitar ou se preparar para ameaças futuras, e está associada a respostas afetivas, fisiológicas e comportamentais características.","referencia":"Borkovec, T. D., Ray, W. J., & Stöber, J. (1998). Worry: A cognitive phenomenon intimately linked to affective, physiological, and interpersonal behavioral processes. Cognitive Therapy and Research, 22(6), 561–576.","link":"https://doi.org/10.1023/a:1018790003416","aplicacao":"Fundamenta a descrição do ciclo da ansiedade e a diferenciação entre preocupação produtiva e ruminação apresentadas na explicação do módulo.","limitacoes":"É um artigo teórico e de revisão de processos cognitivos e fisiológicos, não um ensaio clínico controlado que testou uma intervenção específica."},{"afirmacao":"A ruminação — repetir mentalmente um problema sem chegar a uma solução — está associada a sintomas depressivos e a quadros mistos de ansiedade e depressão, tendendo a prolongar o sofrimento em vez de resolvê-lo.","referencia":"Nolen-Hoeksema, S. (2000). The role of rumination in depressive disorders and mixed anxiety/depressive symptoms. Journal of Abnormal Psychology, 109(3), 504–511.","link":"https://doi.org/10.1037/0021-843X.109.3.504","aplicacao":"Sustenta a distinção do módulo entre preocupação produtiva e ruminação improdutiva, e a ideia de que ruminar tende a piorar o humor sem gerar solução.","limitacoes":"É um estudo focado em sintomas depressivos e mistos, não uma medida diagnóstica; ruminação e preocupação são processos relacionados, mas não idênticos, e os achados não se aplicam automaticamente a todo tipo de preocupação ansiosa."},{"afirmacao":"A dificuldade de tolerar a incerteza (intolerância à incerteza) está associada a mais sintomas de ansiedade, incluindo ansiedade generalizada.","referencia":"Gentes, E. L., & Ruscio, A. M. (2011). A meta-analysis of the relation of intolerance of uncertainty to symptoms of generalized anxiety disorder, major depressive disorder, and obsessive–compulsive disorder. Clinical Psychology Review, 31(6), 923–933.","link":"https://doi.org/10.1016/j.cpr.2011.05.001","aplicacao":"Fundamenta a orientação do módulo sobre praticar aceitar a incerteza em vez de tentar controlar tudo, especialmente na parte do exercício sobre o que está fora de controle.","limitacoes":"É uma meta-análise correlacional — não estabelece que a intolerância à incerteza causa ansiedade, só que as duas aparecem associadas nos estudos analisados."}],"avisoSeguranca":"Se a ansiedade estiver presente quase o tempo todo, atrapalhando o dia a dia de forma incapacitante, ou vier acompanhada de crises intensas (como falta de ar, tontura forte ou pânico), isso vale uma conversa com um profissional de saúde mental — este exercício é um recurso de apoio, não substitui terapia ou acompanhamento clínico.","camposParaTriagem":["controle_total","controle_parcial","fora_de_controle"]}'::jsonb, 1),
  ('22222222-2222-2222-2222-222222222222', 5, 'Dia 5: Perfeccionismo e medo de falhar', 'Entender a diferença entre ter padrões altos e cair em perfeccionismo prejudicial, reconhecer o pensamento "tudo ou nada" e o ciclo entre perfeccionismo, procrastinação e autocrítica, e treinar a ideia de "bom o suficiente para o propósito" através de um pequeno experimento prático.



Ter padrões altos e se dedicar de verdade a algo não é, por si só, um problema — muita gente com exigência saudável entrega um trabalho bom, aprende com erros e ainda assim dorme tranquila à noite. A diferença não está em "quanto" você se importa, mas em como você se relaciona com o resultado: dedicação saudável convive com autocompaixão quando algo sai errado, aceita que "bom" às vezes é suficiente e trata um erro como informação, não como sentença. Perfeccionismo prejudicial é outra coisa: os padrões são rígidos (não se ajustam ao contexto), o valor que você atribui a si mesma fica condicionado ao desempenho, e por mais que o resultado seja bom, quase nunca é "bom o bastante".

Um padrão de pensamento muito comum em quem lida com perfeccionismo é o "tudo ou nada": ou o trabalho fica perfeito, ou é um fracasso completo — não existe meio-termo mentalmente registrado como aceitável. Uma prova com nota 9 vira "eu devia ter tirado 10". Um projeto elogiado por oito de dez pessoas vira, na sua cabeça, "duas pessoas não gostaram, então eu fracassei". Esse tipo de pensamento distorce a régua: ele apaga toda a faixa intermediária de "bom", "suficiente" e "válido mesmo com falhas", e deixa só os dois extremos.

Perfeccionismo, procrastinação e autocrítica costumam formar um ciclo que se alimenta sozinho. O medo de não conseguir fazer algo perfeito faz a tarefa parecer ameaçadora demais para começar — então você adia. Adiar aumenta a pressão do prazo e o volume de trabalho acumulado, o que deixa menos espaço para fazer as coisas com calma. Quando finalmente o resultado sai (sob pressão, correndo, ou nem sai), a autocrítica aparece com força: "eu devia ter começado antes", "isso não ficou bom o bastante", "eu sempre faço isso". Essa autocrítica, em vez de motivar, aumenta o medo da próxima tentativa — e o ciclo recomeça no próximo projeto.

Uma forma de sair desse ciclo é trocar a pergunta "isso está perfeito?" por "isso é bom o suficiente para o que essa tarefa precisa fazer?". Um e-mail rápido para confirmar uma reunião não precisa do mesmo cuidado que uma redação de vestibular; um rascunho não precisa ter o acabamento de uma versão final. Definir, antes de começar, qual é o nível de cuidado realmente necessário para aquele propósito específico ajuda a calibrar o esforço — e libera energia para as coisas que de fato merecem mais atenção.', '{"schemaVersion":1,"objetivo":"Entender a diferença entre ter padrões altos e cair em perfeccionismo prejudicial, reconhecer o pensamento \"tudo ou nada\" e o ciclo entre perfeccionismo, procrastinação e autocrítica, e treinar a ideia de \"bom o suficiente para o propósito\" através de um pequeno experimento prático.","duracaoEstimadaMinutos":9,"explicacao":["Ter padrões altos e se dedicar de verdade a algo não é, por si só, um problema — muita gente com exigência saudável entrega um trabalho bom, aprende com erros e ainda assim dorme tranquila à noite. A diferença não está em \"quanto\" você se importa, mas em como você se relaciona com o resultado: dedicação saudável convive com autocompaixão quando algo sai errado, aceita que \"bom\" às vezes é suficiente e trata um erro como informação, não como sentença. Perfeccionismo prejudicial é outra coisa: os padrões são rígidos (não se ajustam ao contexto), o valor que você atribui a si mesma fica condicionado ao desempenho, e por mais que o resultado seja bom, quase nunca é \"bom o bastante\".","Um padrão de pensamento muito comum em quem lida com perfeccionismo é o \"tudo ou nada\": ou o trabalho fica perfeito, ou é um fracasso completo — não existe meio-termo mentalmente registrado como aceitável. Uma prova com nota 9 vira \"eu devia ter tirado 10\". Um projeto elogiado por oito de dez pessoas vira, na sua cabeça, \"duas pessoas não gostaram, então eu fracassei\". Esse tipo de pensamento distorce a régua: ele apaga toda a faixa intermediária de \"bom\", \"suficiente\" e \"válido mesmo com falhas\", e deixa só os dois extremos.","Perfeccionismo, procrastinação e autocrítica costumam formar um ciclo que se alimenta sozinho. O medo de não conseguir fazer algo perfeito faz a tarefa parecer ameaçadora demais para começar — então você adia. Adiar aumenta a pressão do prazo e o volume de trabalho acumulado, o que deixa menos espaço para fazer as coisas com calma. Quando finalmente o resultado sai (sob pressão, correndo, ou nem sai), a autocrítica aparece com força: \"eu devia ter começado antes\", \"isso não ficou bom o bastante\", \"eu sempre faço isso\". Essa autocrítica, em vez de motivar, aumenta o medo da próxima tentativa — e o ciclo recomeça no próximo projeto.","Uma forma de sair desse ciclo é trocar a pergunta \"isso está perfeito?\" por \"isso é bom o suficiente para o que essa tarefa precisa fazer?\". Um e-mail rápido para confirmar uma reunião não precisa do mesmo cuidado que uma redação de vestibular; um rascunho não precisa ter o acabamento de uma versão final. Definir, antes de começar, qual é o nível de cuidado realmente necessário para aquele propósito específico ajuda a calibrar o esforço — e libera energia para as coisas que de fato merecem mais atenção."],"exemplo":{"titulo":"Um exemplo do dia a dia","texto":"Bianca precisava montar uma apresentação de slides para uma reunião de equipe na sexta-feira. Ela sabia exatamente o que queria dizer desde segunda, mas passou a semana adiando: \"vou abrir o arquivo quando tiver mais tempo para fazer direito\". Na quinta à noite, com só uma noite de sobra, o pensamento que apareceu foi \"não vai dar tempo de ficar bom, é melhor nem entregar do que entregar maltrapilho\". Ela ficou até tarde refazendo os mesmos três slides várias vezes, dormiu quatro horas e ainda achou, no dia seguinte, que a apresentação \"podia ter sido bem melhor\" — mesmo depois de dois colegas elogiarem espontaneamente a clareza dela. Olhando para trás, Bianca percebeu que uma versão simples e direta, feita com calma na segunda-feira, teria cumprido o propósito da reunião tão bem quanto (ou melhor que) a versão de última hora — só que sem a semana inteira de peso e a noite maldormida."},"exercicio":{"introducao":"Este exercício é um experimento comportamental: em vez de só refletir sobre perfeccionismo, a ideia é testar, na prática, o que acontece quando você faz algo \"suficientemente bem\" em vez de \"perfeito\" — e comparar o que sua mente prevê com o que de fato acontece.","campos":[{"tipo":"texto_longo","id":"tarefa_experimento","rotulo":"Escolha uma tarefa pequena e de baixo risco dos próximos dias (algo que, se sair \"só bom\" em vez de perfeito, não vai gerar consequência grave). Descreva qual é essa tarefa e como você pretende fazê-la \"suficientemente bem\" de propósito, em vez de perfeita.","placeholder":"Ex.: vou responder aquele e-mail em duas frases diretas, sem reler cinco vezes, e enviar mesmo sem estar \"perfeito\"...","maxCaracteres":600},{"tipo":"escala","id":"crenca_algo_ruim","rotulo":"Agora, antes de fazer o experimento: o quanto você acredita que algo ruim vai acontecer se você fizer essa tarefa \"só bem\", sem capricho extra?","min":0,"max":10,"rotuloMin":"Nada — não acho que vai dar problema","rotuloMax":"Muito — tenho certeza que vai dar problema"},{"tipo":"texto_curto","id":"resultado_real","rotulo":"Depois de fazer o experimento (pode voltar aqui em outro dia para preencher): o que realmente aconteceu?","placeholder":"Ex.: enviei o e-mail direto, ninguém comentou nada, a reunião aconteceu normalmente...","maxCaracteres":400,"opcional":true}]},"feedback":{"padrao":"Escolher fazer algo \"suficientemente bem\" de propósito, em vez de perfeito, já é um exercício de coragem — mesmo que a mente ainda insista que precisava ser mais. Preste atenção no que realmente acontece depois: costuma ser bem menos dramático do que a antecipação.","regras":[{"id":"crenca-muito-alta","condicoes":[{"campoId":"crenca_algo_ruim","operador":"maior_ou_igual","valor":8}],"texto":"Uma expectativa tão forte de que algo vai dar errado é exatamente o tipo de previsão que o perfeccionismo costuma fazer — e que raramente se confirma no tamanho esperado. Vale fazer o experimento mesmo assim, com curiosidade genuína: você está prestes a coletar um dado real sobre o que de fato acontece, não só sobre o que a mente imagina."},{"id":"crenca-moderada","condicoes":[{"campoId":"crenca_algo_ruim","operador":"maior_ou_igual","valor":4},{"campoId":"crenca_algo_ruim","operador":"menor_ou_igual","valor":7}],"texto":"Existe uma dúvida real aí, e isso é normal — é justamente essa incerteza que o experimento ajuda a testar. Depois de fazer a tarefa, compare o resultado real com esse número: costuma haver uma diferença interessante entre o que a gente teme e o que de fato acontece."},{"id":"crenca-baixa","condicoes":[{"campoId":"crenca_algo_ruim","operador":"menor_ou_igual","valor":3}],"texto":"Que bom que a expectativa de algo dar errado já está baixa — isso pode ser um sinal de que essa tarefa específica é um bom ponto de partida para praticar \"bom o suficiente\" sem tanta resistência interna. Aproveite para notar como é fazer algo com esse nível de exigência mais leve."},{"id":"resultado-preenchido","condicoes":[{"campoId":"resultado_real","operador":"preenchido"}],"texto":"Obrigada por voltar para registrar o que aconteceu de verdade — comparar a previsão com o resultado real é a parte mais valiosa desse tipo de experimento, mesmo quando o resultado foi neutro ou misto."},{"id":"tarefa-descrita","condicoes":[{"campoId":"tarefa_experimento","operador":"preenchido"}],"texto":"Ter uma tarefa concreta e um plano específico de \"como vou fazer isso só o suficiente\" já é metade do trabalho — o resto é permitir que aconteça, mesmo com o desconforto de não capricharmos além do necessário."}]},"acaoPratica":"Nas próximas 24 horas, escolha uma tarefa pequena do seu dia (não precisa ser a do exercício) e faça-a de propósito com \"80% do capricho de sempre\" — e observe se alguém percebe, ou se algo realmente dá errado por causa disso.","resumo":["Padrões altos com autocompaixão são diferentes de perfeccionismo rígido com autovalor condicionado ao desempenho.","O pensamento \"tudo ou nada\" apaga o meio-termo entre \"perfeito\" e \"fracasso total\".","Perfeccionismo, procrastinação e autocrítica costumam formar um ciclo que se retroalimenta.","Perguntar \"isso é bom o suficiente para o propósito?\" ajuda a calibrar o esforço de forma mais realista.","Testar na prática o que acontece quando algo não é perfeito costuma revelar previsões mais assustadoras do que a realidade."],"baseCientifica":[{"afirmacao":"Perfeccionismo não é um traço único: existem dimensões diferentes (perfeccionismo autoorientado, socialmente prescrito e orientado aos outros), com padrões e impactos distintos sobre como a pessoa se relaciona consigo e com os outros.","referencia":"Hewitt, P. L., & Flett, G. L. (1991). Perfectionism in the self and social contexts: Conceptualization, assessment, and association with psychopathology. Journal of Personality and Social Psychology, 60(3), 456–470.","link":"https://doi.org/10.1037/0022-3514.60.3.456","aplicacao":"Fundamenta a distinção entre padrões altos saudáveis e perfeccionismo prejudicial, e a ideia de que \"perfeccionismo\" não é um único fenômeno igual para todo mundo.","limitacoes":"É um estudo de conceitualização e medição de décadas atrás; distingue perfeccionismo autoorientado, socialmente prescrito e orientado aos outros — nem todo perfeccionismo tem o mesmo padrão nem o mesmo impacto, e o instrumento original reflete o contexto de pesquisa da época."},{"afirmacao":"Perfeccionismo está associado a maior sofrimento psicológico (incluindo ansiedade, depressão e outros indicadores de dificuldade emocional), com força de associação variando conforme o tipo de perfeccionismo medido.","referencia":"Limburg, K., Watson, H. J., Hagger, M. S., & Egan, S. J. (2017). The Relationship Between Perfectionism and Psychopathology: A Meta-Analysis. Journal of Clinical Psychology, 73(10), 1301–1326.","link":"https://doi.org/10.1002/jclp.22435","aplicacao":"Fundamenta a explicação sobre o ciclo entre perfeccionismo, autocrítica e sofrimento, e reforça por que vale a pena trabalhar padrões mais flexíveis.","limitacoes":"É uma associação correlacional entre perfeccionismo e sofrimento psicológico — não prova que um causa o outro isoladamente; os tamanhos de efeito variam bastante conforme o tipo de perfeccionismo e a população estudada."}],"camposParaTriagem":["tarefa_experimento","resultado_real"]}'::jsonb, 1),
  ('22222222-2222-2222-2222-222222222222', 6, 'Dia 6: Imagem corporal além da aparência', 'Entender como a comparação social e as redes sociais moldam a relação com o próprio corpo, separar aparência de valor pessoal e de funcionalidade corporal, e reconhecer conteúdos que pioram essa relação — sem qualquer foco em peso, calorias ou dietas.



É quase impossível escapar da comparação: o cérebro compara de forma automática, e redes sociais multiplicam as oportunidades de comparação social a um volume que nenhuma geração anterior enfrentou. O problema não é ver outros corpos — é que boa parte do que aparece no feed é selecionado, editado e postado justamente por mostrar um ângulo, uma luz ou um momento fora do comum, e não é assim que corpos existem no dia a dia, nem o seu, nem o de quem você está vendo. Comparar seu corpo real, em movimento, no espelho de casa, com uma imagem escolhida a dedo entre dezenas de fotos é comparar coisas de naturezas diferentes.

Vale separar três coisas que a cultura costuma embaralhar: aparência (como o corpo parece, de fora), valor pessoal (quem você é, o que você faz, como trata as pessoas, o que te importa) e funcionalidade (o que o corpo faz por você e permite que você viva). Seu valor como pessoa não é uma nota atribuída à sua aparência — e um corpo pode ser fonte de gratidão por tudo que ele possibilita, independentemente de como ele se compara a um padrão estético qualquer.

Na pesquisa em psicologia, existe um conceito chamado "imagem corporal positiva", que vai além de "gostar da aparência" — ele inclui apreciar o corpo pelo que ele faz (funcionalidade), respeitá-lo e cuidar dele, e filtrar de forma crítica as mensagens da cultura sobre como o corpo "deveria" ser. É importante ser clara aqui sobre um ponto: existe também um termo popular, "neutralidade corporal", que fala em focar menos na aparência — nem de forma positiva nem negativa — e mais em outros aspectos da vida e da identidade. Esse termo é parecido, mas não é a mesma coisa que "imagem corporal positiva" estudada academicamente: um foca em apreciar ativamente o corpo (inclusive sua funcionalidade), o outro foca em tirar a aparência do centro da atenção. São conceitos relacionados, mas distintos, e a neutralidade corporal tem, até o momento, bem menos pesquisa científica direta sobre ela do que a imagem corporal positiva.

Reconhecer o que piora sua relação com o corpo é uma habilidade prática. Alguns sinais: sair de um perfil ou de um tipo de conteúdo se sentindo pior do que entrou; perceber que você começa a se comparar automaticamente logo depois de ver certos posts; contas que giram em torno de "antes e depois", corpos idealizados apresentados como padrão único, ou comentários (seus ou de outros) que reduzem pessoas à aparência. Notar esse padrão não é sobre banir redes sociais da sua vida — é sobre perceber o efeito que contas específicas têm em você, e ter mais liberdade de escolha sobre o que consome.', '{"schemaVersion":1,"objetivo":"Entender como a comparação social e as redes sociais moldam a relação com o próprio corpo, separar aparência de valor pessoal e de funcionalidade corporal, e reconhecer conteúdos que pioram essa relação — sem qualquer foco em peso, calorias ou dietas.","duracaoEstimadaMinutos":8,"explicacao":["É quase impossível escapar da comparação: o cérebro compara de forma automática, e redes sociais multiplicam as oportunidades de comparação social a um volume que nenhuma geração anterior enfrentou. O problema não é ver outros corpos — é que boa parte do que aparece no feed é selecionado, editado e postado justamente por mostrar um ângulo, uma luz ou um momento fora do comum, e não é assim que corpos existem no dia a dia, nem o seu, nem o de quem você está vendo. Comparar seu corpo real, em movimento, no espelho de casa, com uma imagem escolhida a dedo entre dezenas de fotos é comparar coisas de naturezas diferentes.","Vale separar três coisas que a cultura costuma embaralhar: aparência (como o corpo parece, de fora), valor pessoal (quem você é, o que você faz, como trata as pessoas, o que te importa) e funcionalidade (o que o corpo faz por você e permite que você viva). Seu valor como pessoa não é uma nota atribuída à sua aparência — e um corpo pode ser fonte de gratidão por tudo que ele possibilita, independentemente de como ele se compara a um padrão estético qualquer.","Na pesquisa em psicologia, existe um conceito chamado \"imagem corporal positiva\", que vai além de \"gostar da aparência\" — ele inclui apreciar o corpo pelo que ele faz (funcionalidade), respeitá-lo e cuidar dele, e filtrar de forma crítica as mensagens da cultura sobre como o corpo \"deveria\" ser. É importante ser clara aqui sobre um ponto: existe também um termo popular, \"neutralidade corporal\", que fala em focar menos na aparência — nem de forma positiva nem negativa — e mais em outros aspectos da vida e da identidade. Esse termo é parecido, mas não é a mesma coisa que \"imagem corporal positiva\" estudada academicamente: um foca em apreciar ativamente o corpo (inclusive sua funcionalidade), o outro foca em tirar a aparência do centro da atenção. São conceitos relacionados, mas distintos, e a neutralidade corporal tem, até o momento, bem menos pesquisa científica direta sobre ela do que a imagem corporal positiva.","Reconhecer o que piora sua relação com o corpo é uma habilidade prática. Alguns sinais: sair de um perfil ou de um tipo de conteúdo se sentindo pior do que entrou; perceber que você começa a se comparar automaticamente logo depois de ver certos posts; contas que giram em torno de \"antes e depois\", corpos idealizados apresentados como padrão único, ou comentários (seus ou de outros) que reduzem pessoas à aparência. Notar esse padrão não é sobre banir redes sociais da sua vida — é sobre perceber o efeito que contas específicas têm em você, e ter mais liberdade de escolha sobre o que consome."],"exemplo":{"titulo":"Um exemplo do dia a dia","texto":"Larissa passava as noites rolando o feed antes de dormir e, várias vezes por semana, fechava o aplicativo se sentindo pior do que quando abriu — sem conseguir dizer exatamente por quê. Um dia ela decidiu prestar atenção: percebeu que era sempre depois de ver um tipo específico de conta, de pessoas com corpos parecidos entre si, em fotos muito trabalhadas, com legendas que insinuavam que aquele era \"o padrão\" a seguir. No dia seguinte, Larissa parou para pensar no que o próprio corpo fazia por ela naquela semana: as pernas que a levaram para dançar com as amigas no sábado, os braços que carregaram a sobrinha pequena no colo, as mãos que fizeram o bolo de aniversário da mãe. Nada daquilo tinha a ver com como o corpo dela se comparava a uma foto na internet. Ela silenciou aquelas contas específicas — não por raiva delas, mas porque percebeu, com clareza, o efeito que tinham nela."},"exercicio":{"introducao":"Vamos praticar duas coisas: notar o que seu corpo faz por você além da aparência, e observar com mais atenção o efeito que certos conteúdos das redes sociais têm em como você se sente.","campos":[{"tipo":"texto_longo","id":"funcoes_corpo","rotulo":"Pense em 2 ou 3 coisas que seu corpo fez por você recentemente e que não têm nada a ver com aparência (ex.: te levou a algum lugar importante, permitiu abraçar alguém, fez algo que você gosta). Escreva esses exemplos.","placeholder":"Ex.: minhas pernas me levaram até a casa da minha avó, minhas mãos escreveram uma carta para uma amiga...","maxCaracteres":600},{"tipo":"texto_longo","id":"conteudo_que_piora","rotulo":"Existe alguma conta ou tipo de conteúdo nas redes sociais que costuma piorar como você se sente com o próprio corpo depois de ver? Se sim, o que é, e o que você poderia fazer a respeito (deixar de seguir, silenciar, limitar o tempo, ou outra coisa)?","placeholder":"Ex.: perfis de \"antes e depois\" me deixam mal, acho que vou silenciar por um tempo...","maxCaracteres":600,"opcional":true}]},"feedback":{"padrao":"Obrigada por parar para notar isso com mais atenção — separar aparência de funcionalidade e de valor pessoal é um exercício que vale a pena repetir sempre que a comparação automática aparecer.","regras":[{"id":"funcoes-preenchidas","condicoes":[{"campoId":"funcoes_corpo","operador":"preenchido"}],"texto":"Reparar no que o corpo faz por você, e não só em como ele parece, é um exercício simples que pode ser repetido a qualquer momento — inclusive em dias em que a relação com a aparência estiver mais difícil."},{"id":"conteudo-identificado","condicoes":[{"campoId":"conteudo_que_piora","operador":"preenchido"}],"texto":"Identificar exatamente qual conteúdo piora como você se sente já é metade do caminho — você não precisa agir sobre isso hoje, mas agora tem mais clareza para escolher o que fazer da próxima vez que aquele conteúdo aparecer."}]},"acaoPratica":"Nas próximas 24 horas, escolha uma conta ou tipo de conteúdo que você notou que piora como se sente com o próprio corpo, e silencie, deixe de seguir ou limite o tempo com ela — sem precisar justificar essa escolha para ninguém.","resumo":["Comparação social é automática, mas o que vemos nas redes é selecionado e editado — comparar não é justo.","Aparência, valor pessoal e funcionalidade do corpo são coisas diferentes, mesmo que a cultura as misture.","\"Imagem corporal positiva\" (conceito estudado cientificamente) e \"neutralidade corporal\" (termo popular) são parecidos, mas não são sinônimos.","Notar o efeito real de contas e conteúdos específicos ajuda a escolher com mais liberdade o que consumir."],"baseCientifica":[{"afirmacao":"Imagem corporal positiva é um constructo próprio (não apenas a ausência de imagem corporal negativa) que inclui apreciação do corpo, valorização de sua funcionalidade e filtragem crítica de mensagens culturais sobre aparência.","referencia":"Tylka, T. L., & Wood-Barcalow, N. L. (2015). What is and what is not positive body image? Conceptual foundations and construct definition. Body Image, 14, 118–129.","link":"https://doi.org/10.1016/j.bodyim.2015.04.001","aplicacao":"Fundamenta a explicação sobre apreciação corporal e funcionalidade do corpo, e embasa a distinção explícita feita no texto entre \"imagem corporal positiva\" (constructo acadêmico) e \"neutralidade corporal\" (termo popular).","limitacoes":"Este estudo trata do constructo acadêmico \"imagem corporal positiva\" e apreciação/funcionalidade corporal — não é um estudo sobre \"neutralidade corporal\" como termo popular, que é um conceito relacionado mas distinto, com menos pesquisa empírica direta até o momento."},{"afirmacao":"O uso de redes sociais, especialmente exposição a imagens idealizadas e comparação social de aparência, está associado a maior preocupação com a imagem corporal.","referencia":"Fardouly, J., & Vartanian, L. R. (2016). Social Media and Body Image Concerns: Current Research and Future Directions. Current Opinion in Psychology, 9, 1–5.","link":"https://doi.org/10.1016/j.copsyc.2015.09.005","aplicacao":"Fundamenta a explicação sobre comparação social nas redes e a parte do exercício que convida a identificar contas ou conteúdos que pioram a relação com o corpo.","limitacoes":"Artigo de revisão majoritariamente sobre mulheres jovens ocidentais usando redes sociais como Facebook e Instagram; efeitos variam por indivíduo e tipo de uso da rede social, e a associação encontrada não é determinística nem se aplica da mesma forma a todo mundo."}],"camposParaTriagem":["funcoes_corpo","conteudo_que_piora"]}'::jsonb, 1),
  ('22222222-2222-2222-2222-222222222222', 7, 'Dia 7: Limites e comunicação assertiva', 'Diferenciar comunicação passiva, agressiva e assertiva, reconhecer sinais de que um limite pessoal foi ultrapassado, praticar pedidos claros e o direito de dizer "não" sem excesso de justificativa, e normalizar a culpa que costuma aparecer depois de estabelecer um limite saudável.



Existem, de forma simplificada, três estilos de comunicação diante de um conflito ou pedido. Na comunicação passiva, você não expressa sua própria necessidade — engole o incômodo, concorda mesmo sem querer, ou espera que a outra pessoa "adivinhe" o que você sente (ex.: uma amiga pede para você trocar de horário pela terceira vez no mês e você diz "tudo bem, sem problema", mesmo estando cansada disso). Na comunicação agressiva, sua necessidade é expressa, mas a da outra pessoa é desrespeitada — no tom, nas palavras ou na forma (ex.: "você sempre faz isso, é um saco combinar qualquer coisa com você"). Na comunicação assertiva, você expressa o que sente e precisa, respeitando também o espaço da outra pessoa (ex.: "percebi que essa é a terceira vez que muda o horário este mês, e isso tem mexido comigo — dá para combinarmos algo que funcione para as duas?"). Nenhum estilo é um "defeito de personalidade": são padrões aprendidos, que podem ser treinados e ajustados.

Reconhecer os próprios limites nem sempre é óbvio, porque muita gente aprende a ignorar os primeiros sinais. Alguns indícios de que um limite foi ultrapassado: irritação que se repete sempre que uma mesma pessoa ou situação aparece; cansaço desproporcional depois de um contato específico; ressentimento acumulado (aquela sensação de "eu não devia ter aceitado isso" que fica remoendo por dias). Esses sinais não significam que você está sendo "difícil" — eles são informação. Quanto antes você perceber esse padrão, mais cedo consegue agir antes que o ressentimento vire uma explosão ou um afastamento silencioso.

Fazer um pedido claro envolve ser específica sobre o quê, e evitar generalizações ("você nunca me ajuda" vira "eu gostaria que você lavasse a louça nos dias em que eu cozinho"). E dizer "não" não exige um parágrafo de justificativa: um "não posso essa semana" ou "isso não funciona para mim agora" já é uma resposta completa. Explicar demais um "não" — numa tentativa de parecer razoável o suficiente para não ser questionada — costuma abrir espaço para que a outra pessoa tente contra-argumentar cada motivo, um por um, até você ceder.

É bastante comum sentir culpa logo depois de estabelecer um limite, mesmo quando esse limite é necessário e saudável — principalmente se você aprendeu, ao longo da vida, que agradar os outros é mais seguro do que priorizar a própria necessidade. Essa culpa não é, necessariamente, um sinal de que você fez algo errado: muitas vezes é só o desconforto de fazer algo diferente do padrão automático. Reconhecer "sinto culpa, e mesmo assim esse limite fazia sentido" é diferente de deixar a culpa decidir por você.', '{"schemaVersion":1,"objetivo":"Diferenciar comunicação passiva, agressiva e assertiva, reconhecer sinais de que um limite pessoal foi ultrapassado, praticar pedidos claros e o direito de dizer \"não\" sem excesso de justificativa, e normalizar a culpa que costuma aparecer depois de estabelecer um limite saudável.","duracaoEstimadaMinutos":9,"explicacao":["Existem, de forma simplificada, três estilos de comunicação diante de um conflito ou pedido. Na comunicação passiva, você não expressa sua própria necessidade — engole o incômodo, concorda mesmo sem querer, ou espera que a outra pessoa \"adivinhe\" o que você sente (ex.: uma amiga pede para você trocar de horário pela terceira vez no mês e você diz \"tudo bem, sem problema\", mesmo estando cansada disso). Na comunicação agressiva, sua necessidade é expressa, mas a da outra pessoa é desrespeitada — no tom, nas palavras ou na forma (ex.: \"você sempre faz isso, é um saco combinar qualquer coisa com você\"). Na comunicação assertiva, você expressa o que sente e precisa, respeitando também o espaço da outra pessoa (ex.: \"percebi que essa é a terceira vez que muda o horário este mês, e isso tem mexido comigo — dá para combinarmos algo que funcione para as duas?\"). Nenhum estilo é um \"defeito de personalidade\": são padrões aprendidos, que podem ser treinados e ajustados.","Reconhecer os próprios limites nem sempre é óbvio, porque muita gente aprende a ignorar os primeiros sinais. Alguns indícios de que um limite foi ultrapassado: irritação que se repete sempre que uma mesma pessoa ou situação aparece; cansaço desproporcional depois de um contato específico; ressentimento acumulado (aquela sensação de \"eu não devia ter aceitado isso\" que fica remoendo por dias). Esses sinais não significam que você está sendo \"difícil\" — eles são informação. Quanto antes você perceber esse padrão, mais cedo consegue agir antes que o ressentimento vire uma explosão ou um afastamento silencioso.","Fazer um pedido claro envolve ser específica sobre o quê, e evitar generalizações (\"você nunca me ajuda\" vira \"eu gostaria que você lavasse a louça nos dias em que eu cozinho\"). E dizer \"não\" não exige um parágrafo de justificativa: um \"não posso essa semana\" ou \"isso não funciona para mim agora\" já é uma resposta completa. Explicar demais um \"não\" — numa tentativa de parecer razoável o suficiente para não ser questionada — costuma abrir espaço para que a outra pessoa tente contra-argumentar cada motivo, um por um, até você ceder.","É bastante comum sentir culpa logo depois de estabelecer um limite, mesmo quando esse limite é necessário e saudável — principalmente se você aprendeu, ao longo da vida, que agradar os outros é mais seguro do que priorizar a própria necessidade. Essa culpa não é, necessariamente, um sinal de que você fez algo errado: muitas vezes é só o desconforto de fazer algo diferente do padrão automático. Reconhecer \"sinto culpa, e mesmo assim esse limite fazia sentido\" é diferente de deixar a culpa decidir por você."],"exemplo":{"titulo":"Um exemplo do dia a dia","texto":"Fernanda emprestava dinheiro para o mesmo colega de trabalho havia meses, sempre \"só até o fim do mês\", e o pagamento nunca vinha no combinado. Da primeira vez ela só disse \"tudo bem, sem pressa\" (passivo), engolindo a irritação. Na quarta vez, quase explodiu: \"isso é falta de consideração, você não liga para o que combina\" (agressivo) — e se sentiu mal depois, porque não era bem isso que queria dizer. Na quinta vez que ele pediu, Fernanda parou antes de responder e organizou o que queria dizer: \"Quando combinamos um prazo e ele não é cumprido sem aviso, eu fico numa posição difícil, porque também tenho contas para pagar. Dessa vez eu não vou poder emprestar.\" Sentiu um aperto no estômago e uma pontada de culpa logo depois de mandar a mensagem — mas o limite fazia sentido, e ela decidiu não apagar o que tinha escrito."},"exercicio":{"introducao":"Pense em uma situação real e recente em que você sentiu que um limite seu foi ultrapassado, ou em que você gostaria de fazer um pedido mais claro para alguém. Vamos usar uma estrutura simples, inspirada em comunicação assertiva, para organizar isso em palavras.","campos":[{"tipo":"texto_longo","id":"situacao","rotulo":"Situação: o que aconteceu, da forma mais objetiva possível (sem julgamento sobre a outra pessoa).","placeholder":"Ex.: minha amiga cancelou nosso encontro em cima da hora pela terceira vez este mês...","maxCaracteres":600},{"tipo":"texto_longo","id":"sentimento","rotulo":"Sentimento: o que você sente em relação a essa situação?","placeholder":"Ex.: eu me sinto frustrada e um pouco desvalorizada...","maxCaracteres":400},{"tipo":"texto_longo","id":"necessidade","rotulo":"Necessidade: o que está por trás desse sentimento? Do que você precisa nessa relação ou situação?","placeholder":"Ex.: eu preciso sentir que meu tempo também é considerado...","maxCaracteres":400},{"tipo":"texto_longo","id":"pedido","rotulo":"Pedido claro: o que você gostaria de pedir, de forma específica e realizável (evite generalizações como \"sempre\" ou \"nunca\")?","placeholder":"Ex.: gostaria que, se precisar cancelar, me avisasse com um dia de antecedência...","maxCaracteres":400},{"tipo":"texto_curto","id":"limite_especifico","rotulo":"Se houver, qual é o limite específico que você quer estabelecer nessa relação a partir de agora?","placeholder":"Ex.: não vou mais remarcar meus próprios planos por causa de cancelamentos de última hora...","maxCaracteres":300,"opcional":true}]},"feedback":{"padrao":"Colocar situação, sentimento, necessidade e pedido em palavras separadas já é um exercício de assertividade em si — mesmo que você nunca chegue a dizer isso em voz alta para a outra pessoa. Isso te dá clareza para escolher, com calma, o que fazer a seguir.","regras":[{"id":"pedido-preenchido","condicoes":[{"campoId":"pedido","operador":"preenchido"}],"texto":"Transformar um incômodo em um pedido específico é uma das partes mais difíceis da comunicação assertiva — reparar se o seu pedido está claro e realizável (algo que a outra pessoa realmente pode fazer) ajuda a aumentar as chances de ser bem recebido."},{"id":"necessidade-preenchida","condicoes":[{"campoId":"necessidade","operador":"preenchido"}],"texto":"Identificar a necessidade por trás do sentimento é o que dá direção ao pedido — sem isso, é fácil ficar só na queixa, sem saber exatamente o que pedir para que a situação melhore."},{"id":"limite-especifico-preenchido","condicoes":[{"campoId":"limite_especifico","operador":"preenchido"}],"texto":"Ter um limite específico nomeado ajuda a reconhecê-lo mais rápido da próxima vez que a situação se repetir — e lembre-se de que sentir culpa ao sustentar esse limite não significa que ele esteja errado."},{"id":"situacao-preenchida","condicoes":[{"campoId":"situacao","operador":"preenchido"}],"texto":"Descrever a situação de forma objetiva, sem embutir julgamento sobre a outra pessoa, costuma facilitar a conversa — é mais fácil alguém ouvir \"isso aconteceu três vezes\" do que \"você é irresponsável\"."}]},"acaoPratica":"Nas próximas 24 horas, escolha uma situação pequena em que normalmente você diria \"sim\" por hábito, e pratique um \"não\" simples e sem justificativa longa — só \"isso não vai dar para mim agora\", e observe como se sente.","resumo":["Comunicação passiva ignora sua necessidade, agressiva ignora a do outro, assertiva respeita as duas.","Irritação repetida, cansaço e ressentimento são sinais de que um limite foi ultrapassado.","Um pedido claro é específico; um \"não\" não precisa de parágrafos de justificativa.","Sentir culpa depois de estabelecer um limite é comum e não significa que o limite estava errado."],"baseCientifica":[{"afirmacao":"O treino de assertividade é uma intervenção com base em evidências para ajudar pessoas a expressar necessidades e limites de forma mais eficaz nas relações, reduzindo padrões de comunicação passiva ou agressiva.","referencia":"Speed, B. C., Goldstein, B. L., & Goldfried, M. R. (2018). Assertiveness training: A forgotten evidence-based treatment. Clinical Psychology: Science and Practice, 25(1), e12216.","link":"https://doi.org/10.1111/cpsp.12216","aplicacao":"Fundamenta a estrutura de comunicação assertiva ensinada no módulo (diferenciação entre estilos passivo, agressivo e assertivo) e o exercício de pedido claro baseado em situação, sentimento, necessidade e pedido.","limitacoes":"Os próprios autores argumentam que o treino de assertividade é historicamente subestudado nas últimas décadas comparado a outras intervenções de TCC; a base de evidência é mais restrita e antiga do que a de intervenções mais estudadas atualmente."}],"avisoSeguranca":"Atenção: as técnicas deste módulo servem para diferenças de comunicação do dia a dia — combinar horários, dividir tarefas, pedir consideração em uma relação que, no fundo, é segura. Se a situação que você descreveu envolve abuso, coerção, controle (por exemplo, alguém que não te deixa sair, decide por você, ameaça, humilha ou machuca fisicamente) ou qualquer forma de violência, de um parceiro, familiar ou qualquer outra pessoa, isso NÃO é um problema de comunicação, e as técnicas de pedido assertivo deste módulo não se aplicam e não devem ser usadas para tentar \"negociar\" a sua própria segurança. Você não precisa formular o pedido perfeito para merecer estar segura. Nesses casos, o caminho é buscar apoio especializado: o CVV (Centro de Valorização da Vida) oferece apoio emocional gratuito e sigiloso 24 horas por dia, pelo telefone 188 ou pelo chat em cvv.org.br — não é um serviço de emergência, mas está disponível para conversar a qualquer hora. Se houver risco imediato à sua integridade física, procure o SAMU (192), uma UPA, um pronto-socorro ou o hospital mais próximo.","camposParaTriagem":["situacao","sentimento","necessidade","pedido"]}'::jsonb, 1),
  ('22222222-2222-2222-2222-222222222222', 8, 'Dia 8: Hábitos e autocuidado possível', 'Entender por que o humor baixo torna mais difícil começar qualquer coisa (mesmo o que normalmente traz bem-estar), por que esperar "sentir vontade" antes de agir costuma manter você presa, e treinar escolher uma ação de autocuidado pequena, específica e realista — diferente de metas grandes e vagas ou de rotinas que viram mais uma cobrança.



Quando o humor está baixo, o corpo e a mente entram numa espécie de economia de energia: fica mais difícil se concentrar, iniciar tarefas, e até coisas que normalmente trazem prazer podem parecer sem graça ou cansativas demais para começar. Isso não é falta de força de vontade — é uma consequência conhecida e esperada de estados de humor baixo, que reduzem tanto a energia disponível quanto a motivação percebida para agir. Reconhecer isso tira um peso: se hoje está mais difícil começar, o problema não é você ser "preguiçosa" ou "fraca".

Existe uma armadilha comum nessa situação: esperar sentir vontade antes de agir. Faz sentido pensar assim — "vou tomar banho quando eu estiver com mais disposição", "vou ligar para minha amiga quando eu estiver melhor". O problema é que, no humor baixo, a vontade tende a não chegar primeiro. Na maioria das vezes, é o contrário: a ação pequena vem primeiro, e um pouco de energia e disposição aparece depois, como consequência de ter feito algo, não como pré-requisito. Esse princípio — agir mesmo sem vontade, em passos pequenos, para gerar movimento — é chamado de ativação comportamental, e é uma das ideias mais estudadas e úteis para sair do ciclo de "não faço nada porque não tenho vontade, e não tenho vontade porque não faço nada".

Por isso, o tamanho da ação importa mais do que parece. Metas grandes e vagas como "vou cuidar mais de mim" ou "preciso mudar minha rotina inteira" costumam falhar justamente porque exigem energia que talvez não esteja disponível agora — e quando não são cumpridas, viram mais uma prova (falsa) de que "você não consegue nada". Uma ação pequena, específica e com hora marcada — "vou tomar um copo de água e ficar 5 minutos no sol na varanda, depois do almoço" — é mais fácil de começar, mais fácil de cumprir, e cada pequena vitória vai reconstruindo, aos poucos, a sensação de que agir é possível.

Vale diferenciar também autocuidado genuíno de cobrança disfarçada de autocuidado. Autocuidado genuíno é algo que realmente recarrega você, mesmo que pequeno e mesmo que imperfeito — um banho mais demorado, ouvir uma música, mandar uma mensagem para alguém querida. Cobrança disfarçada de autocuidado é quando a "rotina de cuidado" vira ela mesma uma fonte de pressão: uma lista rígida de 10 passos (skincare completo, exercício, meditação, diário, leitura...) que, quando não é cumprida por inteiro, gera culpa em vez de bem-estar. Se o "autocuidado" está te deixando mais exausta ou mais culpada, ele deixou de cumprir sua função — e o tamanho ou a rigidez dele é o primeiro lugar para olhar.', '{"schemaVersion":1,"objetivo":"Entender por que o humor baixo torna mais difícil começar qualquer coisa (mesmo o que normalmente traz bem-estar), por que esperar \"sentir vontade\" antes de agir costuma manter você presa, e treinar escolher uma ação de autocuidado pequena, específica e realista — diferente de metas grandes e vagas ou de rotinas que viram mais uma cobrança.","duracaoEstimadaMinutos":8,"explicacao":["Quando o humor está baixo, o corpo e a mente entram numa espécie de economia de energia: fica mais difícil se concentrar, iniciar tarefas, e até coisas que normalmente trazem prazer podem parecer sem graça ou cansativas demais para começar. Isso não é falta de força de vontade — é uma consequência conhecida e esperada de estados de humor baixo, que reduzem tanto a energia disponível quanto a motivação percebida para agir. Reconhecer isso tira um peso: se hoje está mais difícil começar, o problema não é você ser \"preguiçosa\" ou \"fraca\".","Existe uma armadilha comum nessa situação: esperar sentir vontade antes de agir. Faz sentido pensar assim — \"vou tomar banho quando eu estiver com mais disposição\", \"vou ligar para minha amiga quando eu estiver melhor\". O problema é que, no humor baixo, a vontade tende a não chegar primeiro. Na maioria das vezes, é o contrário: a ação pequena vem primeiro, e um pouco de energia e disposição aparece depois, como consequência de ter feito algo, não como pré-requisito. Esse princípio — agir mesmo sem vontade, em passos pequenos, para gerar movimento — é chamado de ativação comportamental, e é uma das ideias mais estudadas e úteis para sair do ciclo de \"não faço nada porque não tenho vontade, e não tenho vontade porque não faço nada\".","Por isso, o tamanho da ação importa mais do que parece. Metas grandes e vagas como \"vou cuidar mais de mim\" ou \"preciso mudar minha rotina inteira\" costumam falhar justamente porque exigem energia que talvez não esteja disponível agora — e quando não são cumpridas, viram mais uma prova (falsa) de que \"você não consegue nada\". Uma ação pequena, específica e com hora marcada — \"vou tomar um copo de água e ficar 5 minutos no sol na varanda, depois do almoço\" — é mais fácil de começar, mais fácil de cumprir, e cada pequena vitória vai reconstruindo, aos poucos, a sensação de que agir é possível.","Vale diferenciar também autocuidado genuíno de cobrança disfarçada de autocuidado. Autocuidado genuíno é algo que realmente recarrega você, mesmo que pequeno e mesmo que imperfeito — um banho mais demorado, ouvir uma música, mandar uma mensagem para alguém querida. Cobrança disfarçada de autocuidado é quando a \"rotina de cuidado\" vira ela mesma uma fonte de pressão: uma lista rígida de 10 passos (skincare completo, exercício, meditação, diário, leitura...) que, quando não é cumprida por inteiro, gera culpa em vez de bem-estar. Se o \"autocuidado\" está te deixando mais exausta ou mais culpada, ele deixou de cumprir sua função — e o tamanho ou a rigidez dele é o primeiro lugar para olhar."],"exemplo":{"titulo":"Um exemplo do dia a dia","texto":"Débora está há alguns dias se sentindo sem energia, e vinha adiando \"organizar a vida\" — arrumar o quarto, responder mensagens atrasadas, voltar a caminhar. Toda vez que pensava nisso como um bloco só, sentia um cansaço ainda maior e desistia antes de começar. Um dia, em vez de pensar em \"organizar a vida\", ela escolheu uma coisa só: separar a louça do café da manhã, por 5 minutos, logo depois de acordar. Não sentiu vontade nenhuma antes de começar — só decidiu tentar. No meio da tarefa, notou que não estava tão ruim quanto imaginava, e depois de terminar sentiu um alívio pequeno, mas real. No dia seguinte, escolheu outra coisa pequena: mandar uma mensagem de voz para uma amiga, só dizendo \"oi, saudade, sumida por uns dias\". Nenhuma das duas ações resolveu o cansaço de Débora, mas cada uma foi uma prova pequena de que agir, mesmo sem vontade, ainda era possível."},"exercicio":{"introducao":"Vamos escolher uma ação de autocuidado pequena e realista para tentar hoje ou amanhã — pequena o suficiente para começar mesmo sem muita energia, e específica o suficiente para não virar só mais uma intenção vaga.","campos":[{"tipo":"escolha_unica","id":"categoria_atividade","rotulo":"Que tipo de atividade pequena você quer tentar?","opcoes":["Descanso (ex.: cochilo curto, ficar deitada sem culpa, silêncio)","Movimento (ex.: alongar, caminhar alguns minutos, dançar uma música)","Conexão social (ex.: mandar uma mensagem, ligar para alguém, ver alguém pessoalmente)","Algo sensorial ou prazeroso (ex.: banho mais demorado, música, cheiro, comida gostosa)","Organizar um pequeno espaço (ex.: arrumar a cama, lavar a louça, limpar a mesa)","Outra coisa (vou descrever)"]},{"tipo":"texto_curto","id":"descricao_atividade","rotulo":"Descreva especificamente o que você vai tentar fazer.","placeholder":"Ex.: tomar um banho mais demorado, com música, por uns 10 minutos","maxCaracteres":200,"opcional":true},{"tipo":"texto_curto","id":"momento_planejado","rotulo":"Quando você pretende tentar isso? (dia e horário ou momento aproximado)","placeholder":"Ex.: hoje à noite, depois do jantar","maxCaracteres":120},{"tipo":"escala","id":"dificuldade_esperada","rotulo":"Numa escala de 0 a 10, o quão difícil você imagina que vai ser começar?","min":0,"max":10,"rotuloMin":"Bem fácil","rotuloMax":"Muito difícil"},{"tipo":"escala","id":"humor_antes","rotulo":"(Preencha antes de tentar, se quiser) Como está seu humor agora?","min":0,"max":10,"rotuloMin":"Bem baixo","rotuloMax":"Bem bom","opcional":true},{"tipo":"escala","id":"humor_depois","rotulo":"(Preencha depois de tentar) Como você se sentiu depois de fazer a atividade?","min":0,"max":10,"rotuloMin":"Bem baixo","rotuloMax":"Bem bom","opcional":true}]},"feedback":{"padrao":"Escolher uma ação pequena e específica, em vez de uma meta grande e vaga, já é uma forma de cuidado — não porque a ação em si é mágica, mas porque ela é possível de cumprir mesmo num dia difícil.","regras":[{"id":"dificuldade-alta","condicoes":[{"campoId":"dificuldade_esperada","operador":"maior_ou_igual","valor":8}],"texto":"Se até essa ação pequena parece muito difícil de começar, talvez ela ainda não esteja pequena o suficiente — tudo bem diminuir mais. Às vezes o primeiro passo real é menor do que a gente imagina: não \"tomar banho\", mas só \"entrar no banheiro\"; não \"sair para caminhar\", mas só \"calçar o tênis\"."},{"id":"dificuldade-baixa","condicoes":[{"campoId":"dificuldade_esperada","operador":"menor_ou_igual","valor":3}],"texto":"Parece uma ação bem acessível para você agora — ótimo ponto de partida. Cumprir algo pequeno e possível vale mais, para reconstruir energia, do que mirar em algo grande que fica só na intenção."},{"id":"categoria-descanso","condicoes":[{"campoId":"categoria_atividade","operador":"igual","valor":"Descanso (ex.: cochilo curto, ficar deitada sem culpa, silêncio)"}],"texto":"Descansar sem culpa também é uma forma de cuidado, mesmo que não pareça \"produtivo\". Você não precisa justificar ou render nada durante esse tempo."},{"id":"categoria-conexao","condicoes":[{"campoId":"categoria_atividade","operador":"igual","valor":"Conexão social (ex.: mandar uma mensagem, ligar para alguém, ver alguém pessoalmente)"}],"texto":"Buscar conexão, mesmo em pequena dose, costuma ajudar bastante quando o humor está baixo — nem que seja uma mensagem curta. Não precisa ser uma conversa longa ou \"perfeita\" para contar."},{"id":"humor-melhorou","condicoes":[{"campoId":"humor_antes","operador":"preenchido"},{"campoId":"humor_depois","operador":"preenchido"}],"texto":"Obrigada por registrar o antes e o depois — comparar os dois números, com o tempo, ajuda a perceber que agir (mesmo sem vontade) costuma mudar como você se sente, ainda que nem sempre de forma grande ou imediata."},{"id":"outra-atividade","condicoes":[{"campoId":"categoria_atividade","operador":"igual","valor":"Outra coisa (vou descrever)"}],"texto":"Você conhece melhor do que ninguém o que costuma te fazer bem — confiar nessa escolha própria também faz parte do processo."}]},"acaoPratica":"Nas próximas 24 horas, tente cumprir a ação pequena que você planejou aqui, mesmo que não sinta vontade na hora de começar. Se não der certo hoje, tudo bem — escolha de novo amanhã, talvez uma versão ainda menor.","resumo":["O humor baixo reduz energia e motivação — isso não é falta de força de vontade.","A motivação geralmente vem depois de começar a agir, não antes: não é preciso \"sentir vontade\" para dar o primeiro passo.","Ações pequenas, específicas e com hora marcada funcionam melhor do que metas grandes e vagas.","Autocuidado genuíno recarrega, mesmo que pequeno; uma rotina rígida que vira fonte de culpa deixou de cumprir essa função."],"baseCientifica":[{"afirmacao":"Hábitos e comportamentos de saúde (incluindo os de autocuidado) se formam e se sustentam de forma mais consistente quando são construídos como ações pequenas e específicas, repetidas em contexto, em vez de intenções amplas.","referencia":"Gardner, B. (2015). A review and analysis of the use of ''habit'' in understanding, predicting and influencing health-related behaviour. Health Psychology Review, 9(3), 277–295.","link":"https://doi.org/10.1080/17437199.2013.876238","aplicacao":"Fundamenta a orientação de escolher uma ação pequena e concreta (categoria + descrição + horário) em vez de uma meta vaga como \"cuidar mais de mim\".","limitacoes":"É uma revisão conceitual sobre a definição e o uso do termo \"hábito\" na pesquisa, não um ensaio testando uma intervenção específica; a formação de hábito varia muito entre pessoas e entre tipos de comportamento, então não há garantia de que uma ação pequena vire hábito automaticamente."},{"afirmacao":"Incentivar a pessoa a se engajar em atividades (ativação comportamental), mesmo sem esperar sentir vontade antes, é eficaz para melhorar sintomas de humor baixo.","referencia":"Cuijpers, P., van Straten, A., & Warmerdam, L. (2007). Behavioral activation treatments of depression: A meta-analysis. Clinical Psychology Review, 27(3), 318–326.","link":"https://doi.org/10.1016/j.cpr.2006.11.001","aplicacao":"Fundamenta a explicação central do módulo: a ideia de que a ação tende a vir antes da motivação, e de que agir em passos pequenos ajuda a sair do ciclo de humor baixo e inatividade.","limitacoes":"É uma meta-análise de tratamentos estruturados de ativação comportamental conduzidos por profissionais para depressão; este módulo usa o princípio geral de forma leve e educativa, em formato de autoajuda guiada, não como substituto de um tratamento formal ou de acompanhamento profissional."}],"camposParaTriagem":["descricao_atividade"]}'::jsonb, 1),
  ('22222222-2222-2222-2222-222222222222', 9, 'Dia 9: Prevenção de recaídas e plano pessoal', 'Entender que voltar a se sentir pior depois de um período melhor é parte comum do processo de mudança, não um fracasso, e construir um plano pessoal simples — sinais de alerta, estratégias que já funcionaram, pessoas de confiança e quando buscar ajuda profissional — para ter à mão num momento difícil.



Depois de um período em que as coisas estavam melhores, é comum — e esperado — que em algum momento venha uma fase mais difícil de novo: o humor cai, padrões antigos voltam, aquilo que você vinha enfrentando parece maior outra vez. Isso costuma ser chamado de "recaída", mas o nome pode enganar: não significa que todo o progresso anterior foi apagado ou que ele "não valeu". Mudança emocional raramente é uma linha reta para cima — é mais parecida com uma trilha com subidas, descidas e platôs. Uma fase mais difícil depois de um período melhor é parte esperada desse caminho, não uma exceção vergonhosa nele.

Por isso, faz diferença aprender a notar os sinais iniciais de que as coisas estão ficando mais difíceis, antes que fiquem grandes. Cada pessoa tem os seus próprios sinais, mas alguns exemplos comuns são: mudanças no sono (dormir muito mais ou muito menos do que o costume), começar a se isolar de pessoas ou atividades que antes faziam parte do dia a dia, irritabilidade maior do que o normal, e voltar a evitar coisas que você vinha, aos poucos, conseguindo enfrentar. Perceber esses sinais cedo dá mais espaço de manobra do que perceber só quando a dificuldade já está grande — não para "impedir" a fase difícil de acontecer, mas para reagir a ela com mais cuidado e menos surpresa.

Uma das partes mais úteis de um plano como esse é reunir, num só lugar, o que você já sabe que funciona para você — em vez de ter que reinventar tudo bem no momento em que menos energia e clareza vai ter disponíveis. Isso pode incluir práticas dos módulos anteriores desta jornada (nomear emoções, questionar pensamentos automáticos, autocompaixão, ações pequenas de autocuidado) ou qualquer outra coisa da sua vida que já se mostrou útil antes, mesmo que pareça simples. Ter essa lista pronta de antemão é diferente de tentar se lembrar dela no meio de um momento difícil.

Outra parte essencial é nomear pessoas de confiança específicas — não "alguém" de forma genérica, mas pessoas reais que você poderia procurar. Saber, de antemão, quem são essas pessoas torna muito mais fácil pedir apoio na hora, quando pedir ajuda costuma parecer mais difícil do que em qualquer outro momento. E, junto com isso, vale reconhecer com clareza quando uma fase difícil pede mais do que autocuidado e apoio de pessoas próximas: quando os sinais de alerta persistem por várias semanas, quando começam a afetar seu funcionamento no dia a dia (trabalho, estudos, relações, cuidados básicos), ou quando aparece qualquer pensamento de se machucar, é hora de buscar ajuda profissional — e isso não é um sinal de que você falhou, é o próprio plano funcionando como deveria.', '{"schemaVersion":1,"objetivo":"Entender que voltar a se sentir pior depois de um período melhor é parte comum do processo de mudança, não um fracasso, e construir um plano pessoal simples — sinais de alerta, estratégias que já funcionaram, pessoas de confiança e quando buscar ajuda profissional — para ter à mão num momento difícil.","duracaoEstimadaMinutos":10,"explicacao":["Depois de um período em que as coisas estavam melhores, é comum — e esperado — que em algum momento venha uma fase mais difícil de novo: o humor cai, padrões antigos voltam, aquilo que você vinha enfrentando parece maior outra vez. Isso costuma ser chamado de \"recaída\", mas o nome pode enganar: não significa que todo o progresso anterior foi apagado ou que ele \"não valeu\". Mudança emocional raramente é uma linha reta para cima — é mais parecida com uma trilha com subidas, descidas e platôs. Uma fase mais difícil depois de um período melhor é parte esperada desse caminho, não uma exceção vergonhosa nele.","Por isso, faz diferença aprender a notar os sinais iniciais de que as coisas estão ficando mais difíceis, antes que fiquem grandes. Cada pessoa tem os seus próprios sinais, mas alguns exemplos comuns são: mudanças no sono (dormir muito mais ou muito menos do que o costume), começar a se isolar de pessoas ou atividades que antes faziam parte do dia a dia, irritabilidade maior do que o normal, e voltar a evitar coisas que você vinha, aos poucos, conseguindo enfrentar. Perceber esses sinais cedo dá mais espaço de manobra do que perceber só quando a dificuldade já está grande — não para \"impedir\" a fase difícil de acontecer, mas para reagir a ela com mais cuidado e menos surpresa.","Uma das partes mais úteis de um plano como esse é reunir, num só lugar, o que você já sabe que funciona para você — em vez de ter que reinventar tudo bem no momento em que menos energia e clareza vai ter disponíveis. Isso pode incluir práticas dos módulos anteriores desta jornada (nomear emoções, questionar pensamentos automáticos, autocompaixão, ações pequenas de autocuidado) ou qualquer outra coisa da sua vida que já se mostrou útil antes, mesmo que pareça simples. Ter essa lista pronta de antemão é diferente de tentar se lembrar dela no meio de um momento difícil.","Outra parte essencial é nomear pessoas de confiança específicas — não \"alguém\" de forma genérica, mas pessoas reais que você poderia procurar. Saber, de antemão, quem são essas pessoas torna muito mais fácil pedir apoio na hora, quando pedir ajuda costuma parecer mais difícil do que em qualquer outro momento. E, junto com isso, vale reconhecer com clareza quando uma fase difícil pede mais do que autocuidado e apoio de pessoas próximas: quando os sinais de alerta persistem por várias semanas, quando começam a afetar seu funcionamento no dia a dia (trabalho, estudos, relações, cuidados básicos), ou quando aparece qualquer pensamento de se machucar, é hora de buscar ajuda profissional — e isso não é um sinal de que você falhou, é o próprio plano funcionando como deveria."],"exemplo":{"titulo":"Um exemplo do dia a dia","texto":"Camila passou os últimos meses trabalhando bastante em si mesma: aprendeu a nomear emoções com mais precisão, praticou ser menos dura consigo mesma nos erros, e sentia que estava, aos poucos, melhor. Num mês mais pesado no trabalho, percebeu que voltou a dormir mal, cancelou dois encontros com amigas seguidos \"porque não tinha energia\", e sentiu uma vontade maior de se isolar no quarto depois do trabalho. No início, pensou \"acho que estraguei tudo que eu vinha construindo\". Mas, olhando o plano que tinha escrito num momento mais estável, reconheceu ali mesmo os seus sinais de alerta (sono, isolamento) escritos por ela mesma semanas antes. Em vez de se cobrar, seguiu o próprio plano: mandou mensagem para a irmã, com quem tinha combinado que podia ser sincera nesses momentos, e voltou a fazer, mesmo sem muita vontade, um exercício pequeno de nomear emoções que já tinha te ajudado antes. A fase difícil não desapareceu da noite para o dia, mas Camila não precisou atravessá-la do zero, sem nenhum apoio."},"exercicio":{"introducao":"Este é o seu plano pessoal — um documento simples para guardar e consultar quando as coisas ficarem mais difíceis. Não precisa ser perfeito nem definitivo: você pode revisá-lo sempre que quiser.","campos":[{"tipo":"texto_longo","id":"sinais_de_alerta","rotulo":"Quais costumam ser os seus sinais iniciais de que as coisas estão começando a piorar?","placeholder":"Ex.: durmo pior, começo a cancelar coisas com amigas, fico mais irritada, evito responder mensagens...","maxCaracteres":600},{"tipo":"texto_longo","id":"estrategias_que_ajudaram","rotulo":"Que ações ou estratégias já te ajudaram no passado (nesta jornada ou na sua vida em geral)?","placeholder":"Ex.: nomear o que estou sentindo, escrever sobre o dia, sair para caminhar, conversar com minha irmã...","maxCaracteres":600},{"tipo":"texto_longo","id":"pessoas_de_confianca","rotulo":"Quem são pessoas de confiança que você poderia procurar num momento difícil?","placeholder":"Pode escrever só como você se refere a elas, sem precisar de nome completo: \"minha irmã\", \"minha amiga X\", \"minha prima\"...","maxCaracteres":400},{"tipo":"texto_longo","id":"quando_buscar_ajuda_profissional","rotulo":"Como você vai reconhecer que é hora de buscar ajuda profissional?","placeholder":"Ex.: quando os sinais de alerta persistem por mais de duas semanas, ou quando aparece qualquer pensamento de me machucar","maxCaracteres":500}]},"feedback":{"padrao":"Você acabou de escrever, com suas próprias palavras, um plano que pode ajudar a versão futura de você num momento mais difícil. Guardar isso agora, enquanto está com mais clareza, é um cuidado real com quem você pode ser daqui a algumas semanas ou meses.","regras":[{"id":"sinais-preenchidos","condicoes":[{"campoId":"sinais_de_alerta","operador":"preenchido"}],"texto":"Conhecer os seus próprios sinais de alerta é uma das partes mais valiosas deste plano — eles são o aviso antecipado que só você consegue reconhecer em si mesma."},{"id":"estrategias-preenchidas","condicoes":[{"campoId":"estrategias_que_ajudaram","operador":"preenchido"}],"texto":"Ótimo ter essa lista pronta. Num momento difícil, com menos energia e clareza disponíveis, é muito mais fácil seguir uma lista que você já escreveu do que tentar lembrar ou inventar algo do zero."},{"id":"pessoas-preenchidas","condicoes":[{"campoId":"pessoas_de_confianca","operador":"preenchido"}],"texto":"Ter nomes específicos em mente, em vez de \"alguém\" de forma vaga, costuma tornar bem mais fácil pedir apoio quando é mais difícil pedir. Se conseguir, considere avisar essas pessoas de que elas estão na sua lista."},{"id":"quando-buscar-ajuda-preenchido","condicoes":[{"campoId":"quando_buscar_ajuda_profissional","operador":"preenchido"}],"texto":"Reconhecer com antecedência quando vale buscar ajuda profissional não é admitir derrota — é parte de um plano de cuidado bem construído, tanto quanto qualquer uma das outras partes."}]},"acaoPratica":"Nas próximas 24 horas, salve este plano em um lugar de fácil acesso (uma nota no celular, um lugar que você volte com frequência) e, se fizer sentido, compartilhe pelo menos uma parte dele com uma das pessoas de confiança que você listou aqui.","resumo":["Uma fase mais difícil depois de um período melhor é parte comum do processo, não um fracasso.","Notar os sinais de alerta cedo dá mais espaço para reagir com cuidado, antes que a dificuldade fique grande.","Ter uma lista pronta de estratégias que já funcionaram evita ter que reinventar tudo num momento difícil.","Nomear pessoas de confiança específicas facilita pedir apoio quando isso fica mais difícil.","Saber quando buscar ajuda profissional é parte do plano, não um sinal de que ele falhou."],"baseCientifica":[{"afirmacao":"Ter um plano estruturado — que inclui identificar sinais de alerta antecipados e estratégias de enfrentamento previamente definidas — ajuda a lidar melhor com um retorno a padrões antigos depois de um período de melhora.","referencia":"Witkiewitz, K., & Marlatt, G. A. (2004). Relapse prevention for alcohol and drug problems: That was Zen, this is Tao. American Psychologist, 59(4), 224–235.","link":"https://doi.org/10.1037/0003-066X.59.4.224","aplicacao":"Inspira a estrutura geral deste módulo de encerramento: identificar sinais de alerta pessoais, reunir estratégias que já funcionaram, nomear rede de apoio e definir quando buscar ajuda, organizados como um plano escrito para consulta futura.","limitacoes":"Este modelo foi originalmente desenvolvido e testado no contexto de dependência química e uso de álcool — sua aplicação aqui, para sinais gerais de piora emocional (não relacionados a substâncias), é uma adaptação conceitual do princípio de \"plano de prevenção de recaída\", não uma extensão diretamente validada por pesquisa para esse uso. O termo \"recaída\" é usado neste módulo de forma ampla e não-clínica, para descrever qualquer retorno a um padrão emocional mais difícil."}],"avisoSeguranca":"Este plano é um recurso de autocuidado e organização pessoal — ele não substitui uma avaliação profissional, e o app não tem como prever ou identificar uma crise com certeza. Se em algum momento os sinais de alerta persistirem por várias semanas, afetarem seu dia a dia, ou vier qualquer pensamento de se machucar, considere buscar apoio: o CVV (Centro de Valorização da Vida) oferece apoio emocional gratuito e sigiloso 24 horas por dia, pelo telefone 188 ou pelo chat em cvv.org.br — não é um serviço de emergência, mas está disponível a qualquer hora para conversar. Em caso de risco imediato, procure o SAMU (192), uma UPA, um pronto-socorro ou o hospital mais próximo.","camposParaTriagem":["sinais_de_alerta","estrategias_que_ajudaram","pessoas_de_confianca","quando_buscar_ajuda_profissional"]}'::jsonb, 1);

